(window.EX_CHUNKS=window.EX_CHUNKS||{})["b48"]={"受不了":[["这天气实在太热了，我快要受不了了。","بۇ ھاۋا ھەقىقەتەن بەك ئىسسىق، مەن بەكلا چىدىيالماي قالدىم.","bu hawa heqiqeten bek issiq, men bekla chidiyalmay qaldim."]],"熬夜":[["为了赶项目，他昨晚熬夜了。","تۈرنى ۋاقتىدا تۈگىتىش ئۈچۈن، ئۇ كەچتە ئۇخلىمىدى.","türni waqtida tügitish üchün, u kechte uxlimidi."]],"内幕":[["他掌握了公司的内幕消息。","ئۇ شىركەتنىڭ ئىچكى ئۇچۇرلىرىنى ئىگىلىۋالغان.","u shirketning ichki uchurlirini igiliwalghan."]],"滔滔不绝":[["他一谈起自己的爱好就滔滔不绝。","ئۇ ئۆزىنىڭ قىزىقىشى توغرىسىدا سۆزلەشكە باشلىسا، ئېغىزىدىن سۆز چۈشمەيدۇ.","u özining qiziqishi toghrisida sözleshke bashlisa, éghizidin söz chüshmeydu."]],"元宵节":[["元宵节家家户户都吃汤圆。","چاڭيۈەن بايرىمىدا ھەر بىر ئائىلە تاڭيۈەن يەيدۇ.","changyüen bayrimida her bir aile tangyüen yeydu."]],"懰":[["他显得十分懰然。","ئۇ ئىنتايىن خۇشال ھالەتتە كۆرۈندى.","u intayin xushal halette köründi."]],"摰":[["他摰着下巴，陷入深深的思考。","ئۇ ئىڭىكىنى تىرەپ، چوڭقۇر ئويغا پاتتى.","u ingikini tirep, chongqur oygha patti."]],"㧰":[["他㧰起袖子，开始劳动。","ئۇ يەڭلىرىنى تۈرۈپ، ئەمگەككە كىرىشتى.","u yenglirini türüp, emgekke kirishti."]],"攰":[["他攰得浑身无力。","ئۇ ھارغىنلىقتىن ھالىدىن كەتتى.","u harghinliqtin halidin ketti."]],"澰":[["澰水缓缓地流向远方。","ليەنشۇي دەرياسى ئاستا-ئاستا يىراققا ئېقىپ بارىدۇ.","lyenshuy deryasi asta-asta yiraqqa éqip baridu."]],"筰":[["筰竹的纤维可以用来造纸。","جۇڭگۇ تالاسىدىن قەغەز ياسىغىلى بولىدۇ.","junggu talasidin qeghez yasighili bolidu."]],"榰":[["榰木的树皮有药用价值。","جى دەرىخىنىڭ پوستىنىڭ دورىلىق قىممىتى بار.","ji derixining postining doriliq qimmiti bar."]],"醰":[["醰酒带有独特的果香。","ئېچىتىلغان ھاراق ئۆزگىچە مېۋە پۇرىقىغا ئىگە.","échitilghan haraq özgiche méwe puriqigha ige."]],"鸰":[["鸰鸟通常在春季繁殖。","لىڭ قۇشى ئادەتتە باھاردا كۆپىيىدۇ.","ling qushi adette baharda köpiyidu."]],"一字不识":[["他从小识字不多，至今几乎一字不识。","ئۇ كىچىكىدىن خەت ئاز تونۇيتتى، ھازىرغىچە بىر خەتمۇ تونۇمايدۇ دېيىشكە بولىدۇ.","u kichikidin xet az tonuytti, hazirghiche bir xetmu tonumaydu déyishke bolidu."]],"一派谎言":[["那全是一派谎言。","ئۇلارنىڭ ھەممىسى پۈتۈنلەي يالغان.","ularning hemmisi pütünley yalghan."]],"一声":[["他一声不吭地走了。","ئۇ ھېچقانداق گەپ قىلماي كېتىپ قالدى.","u héchqandaq gep qilmay kétip qaldi."]],"一声不吭":[["他一声不吭地离开了房间。","ئۇ ھېچقانداق گەپ قىلماي ئۆيدىن چىقىپ كەتتى.","u héchqandaq gep qilmay öydin chiqip ketti."]],"丁丁炒面":[["这家店的丁丁炒面味道独特，深受顾客喜爱。","بۇ دۇكاننىڭ دىڭدىڭ قورۇلغان ئۇگرىسىنىڭ تەمى ئالاھىدە، خېرىدارلارنىڭ ياقتۇرۇشىغا ئېرىشكەن.","bu dukanning dingding qorulghan ugrisining temi alahide, xéridarlarning yaqturushigha érishken."]],"丁丑":[["丁丑年出生的他，性格沉稳，做事可靠。","دىڭچۇ يىلى تۇغۇلغان ئۇ، مىجەزى ئېغىر-بېسىق، ئىش قىلىشتا ئىشەنچلىك.","dingchu yili tughulghan u, mijezi éghir-bésiq, ish qilishta ishenchlik."]],"三无企业":[["三无企业难以监管。","ئۈچ خىل كەمچىلىكى بار كارخانىلارنى نازارەت قىلىش قىيىن.","üch xil kemchiliki bar karxanilarni nazaret qilish qiyin."]],"三代同堂":[["他们三代同堂，其乐融融。","ئۇلار ئۈچ ئەۋلاد بىر ئۆيدە ياشاپ، خۇشال-خۇرام.","ular üch ewlad bir öyde yashap, xushal-xuram."]],"三趾鸥":[["三趾鸥在海岸线上飞翔。","ئۈچ بارماقلىق چاغچىقى دېڭىز قىرغىقىدا ئۇچىدۇ.","üch barmaqliq chaghchiqi déngiz qirghiqida uchidu."]],"三里河":[["三里河是一条小河。","سان لى خې كىچىك بىر دەريا.","san li xé kichik bir derya."]],"不可避免":[["失败是不可避免的。","مەغلۇبىيەت بولمىسا بولمايدۇ.","meghlubiyet bolmisa bolmaydu."]],"不孝":[["不孝令人谴责。","ئانا-ئاتىغا ئىتائەتسىزلىك ئەيىبلەشكە ئەرزىيدۇ.","ana-atigha itaetsizlik eyibleshke erziydu."]],"不寒而栗":[["听到那个恐怖的故事，我不寒而栗。","ئۇ دەھشەتلىك ھېكايىنى ئاڭلاپ، بەدىنىم تىترەپ كەتتى.","u dehshetlik hékayini anglap, bedinim titrep ketti."]],"不插电":[["他喜欢不插电音乐。","ئۇ ئېلېكترىسىز مۇزىكىنى ياخشى كۆرىدۇ.","u éléktrisiz muzikini yaxshi köridu."]],"不吝":[["他毫不吝啬地分享了经验。","ئۇ ھېچقانداق بېخىللىق قىلماي تەجرىبىسىنى ئورتاقلاشتى.","u héchqandaq béxilliq qilmay tejribisini ortaqlashti."]],"丫髻":[["古代女子常梳丫髻发式。","قەدىمكى زاماندا ئاياللار كۆپىنچە قوش چاچ باغلايتتى.","qedimki zamanda ayallar köpinche qosh chach baghlaytti."]],"中石化":[["中石化是中国大型能源企业。","جۇڭشىخۇا جۇڭگونىڭ چوڭ ئېنېرگىيە كارخانىسى.","jungshixua junggoning chong énérgiye karxanisi."]],"串换":[["他们串换了座位。","ئۇلار ئورۇنلىرىنى ئالماشتۇردى.","ular orunlirini almashturdi."]],"久慕":[["我久慕您的才华。","مەن كۆپتىن بۇيان سىزنىڭ تالانتىڭىزغا ھەۋەس قىلىمەن.","men köptin buyan sizning talantingizgha hewes qilimen."]],"中都":[["中都曾是古代的重要都城。","جۇڭدۇ ئەسلىدە قەدىمكى زاماننىڭ مۇھىم پايتەختى بولغان.","jungdu eslide qedimki zamanning muhim paytexti bolghan."]],"中央执行委员会":[["中央执行委员会负责决策。","مەركىزىي ئىجرائىيە كومىتېتى قارار چىقىرىشقا مەسئۇلدۇر.","merkiziy ijraiye komitéti qarar chiqirishqa mes'uldur."]],"干面":[["这种干面口感劲道，适合煮汤。","بۇ خىل قۇرۇق ئۇننىڭ تەملىكى چىڭ، شورپا قاينىتىشقا ماس كېلىدۇ.","bu xil quruq unning temliki ching, shorpa qaynitishqa mas kélidu."]],"交叉熵":[["交叉熵用于衡量信息量。","كرېست ئېنتروپىيە ئۇچۇر مىقدارىنى ئۆلچەشكە ئىشلىتىلىدۇ.","krést éntropiye uchur miqdarini ölcheshke ishlitilidu."]],"交通协管员":[["交通协管员协助维持道路秩序。","قاتناش ياردەمچىسى يول تەرتىپىنى ساقلاشقا ياردەم قىلىدۇ.","qatnash yardemchisi yol tertipini saqlashqa yardem qilidu."]],"交通车":[["公司派来接我们的交通车准时到了。","شىركەت بىزنى ئېلىپ كېلىشكە ئەۋەتكەن قاتناش ماشىنىسى ۋاقتىدا يېتىپ كەلدى.","shirket bizni élip kélishke ewetken qatnash mashinisi waqtida yétip keldi."]],"交际花":[["她被誉为社交界的交际花。","ئۇ جەمئىيەت ساھەسىنىڭ ئارىلىشىش گۈلى دەپ تەرىپلەنگەن.","u jem'iyet sahesining arilishish güli dep teriplengen."]],"亦或":[["你可以选择亦或方案。","سىز ياكى بىلەن لايىھەنى تاللىيالايسىز.","siz yaki bilen layiheni talliyalaysiz."]],"人身安全":[["确保人身安全是首要任务。","شەخس بىخەتەرلىكىنى كاپالەتكە ئىگە قىلىش ئەڭ مۇھىم ۋەزىپە.","shexs bixeterlikini kapaletke ige qilish eng muhim wezipe."]],"人造天体":[["人造天体由人类制造。","سۈنئىي ئاسمان جىسىملىرى ئىنسانلار تەرىپىدىن ياسىلىدۇ.","sün'iy asman jisimliri insanlar teripidin yasilidu."]],"京东":[["京东地区近年来发展迅速，吸引了大量投资。","جىڭدۇڭ رايونى يېقىنقى يىللاردا تېز تەرەققىي قىلىپ، كۆپ مىقداردا مەبلەغنى جەلپ قىلدى.","jingdung rayoni yéqinqi yillarda téz tereqqiy qilip, köp miqdarda mebleghni jelp qildi."]],"人为财死，鸟为食亡":[["人为财死，鸟为食亡，自古如此。","ئادەم بايلىق ئۈچۈن ئۆلىدۇ، قۇش يېمەكلىك ئۈچۈن ئۆلىدۇ، قەدىمدىن تارتىپ شۇنداق.","adem bayliq üchün ölidu, qush yémeklik üchün ölidu, qedimdin tartip shundaq."]],"仁心仁术":[["医生以仁心仁术救治病人。","دوختۇر مېھرىبان قەلب ۋە مېھرىبان تېببىي ماھارەت بىلەن بېمارلارنى داۋالايدۇ.","doxtur méhriban qelb we méhriban tébbiy maharet bilen bémarlarni dawalaydu."]],"人口红利":[["国家依靠人口红利推动了经济发展。","دۆلەت نۇپۇس بونۇسىغا تايىنىپ ئىقتىسادىي تەرەققىياتنى ئىلگىرى سۈردى.","dölet nupus bonusigha tayinip iqtisadiy tereqqiyatni ilgiri sürdi."]],"人口贩运":[["人口贩运是严重的国际犯罪行为。","نۇپۇس ئېلىپ سېتىش ئېغىر خەلقئارالىق جىنايەت.","nupus élip sétish éghir xelq'araliq jinayet."]],"今人":[["今人常常感叹古人的智慧。","بۈگۈنكى كىشىلەر كۆپىنچە قەدىمكىلەرنىڭ ئەقلىگە ھەيران قېلىدۇ.","bügünki kishiler köpinche qedimkilerning eqlige heyran qélidu."]],"仁言利博":[["仁言利博，古人常以此教导后人。","ئىنسانپەرۋەر سۆزنىڭ پايدىسى كەڭ، قەدىمكىلەر بۇنى كۆپىنچە كېيىنكىلەرگە ئۆگەتكەن.","insanperwer sözning paydisi keng, qedimkiler buni köpinche kéyinkilerge ögetken."]],"仰卧起坐":[["每天做仰卧起坐能增强核心力量。","ھەر كۈنى ئارقىسىغا قاراپ ئولتۇرۇپ تۇرۇش مەشىقىنى قىلىش ئاساسىي كۈچنى كۈچەيتەلەيدۇ.","her küni arqisigha qarap olturup turush meshiqini qilish asasiy küchni kücheyteleydu."]],"伊人":[["伊人正在花园里赏花。","ئۇ گۈلزارلىقتا گۈل تاماشا قىلىۋاتىدۇ.","u gülzarliqta gül tamasha qiliwatidu."]],"伊通满族自治县":[["伊通满族自治县位于吉林省。","ئىتۇڭ مانجۇ ئاپتونوم ناھىيىسى جىلىن ئۆلكىسىدە جايلاشقان.","itung manju aptonom nahiyisi jilin ölkiside jaylashqan."]],"布道":[["牧师在教堂里进行布道。","پوپ ئېچىردا ۋەز ئېيتىدۇ.","pop échirda wez éytidu."]],"佛坪县":[["佛坪县以茶叶闻名全国。","فوپىڭ ناھىيىسى چاي بىلەن پۈتۈن مەملىكەتكە تونۇلغان.","foping nahiyisi chay bilen pütün memliketke tonulghan."]],"佳境":[["这里宛如人间仙境，堪称佳境。","بۇ يەر خۇددى دۇنيادىكى جەننەتكە ئوخشايدۇ، ئېسىل مەنزىرە دېيىشكە بولىدۇ.","bu yer xuddi dunyadiki jennetke oxshaydu, ésil menzire déyishke bolidu."]],"来电":[["有来电，请接听。","تېلېفون كەلدى، ئاڭلاڭ.","téléfon keldi, anglang."]],"侗剧":[["侗剧是侗族的传统表演艺术。","دۇڭ تىياتىرى دۇڭ مىللىتىنىڭ ئەنئەنىۋى ئىپادىلەش سەنئىتىدۇر.","dung tiyatiri dung millitining en'eniwi ipadilesh sen'itidur."]],"便意":[["感到便意时，应尽快如厕。","تەرەت قىلىش ئېھتىياجىنى ھېس قىلغاندا، ئەڭ تېز ھالدا ھاجەتخانىغا بېرىش كېرەك.","teret qilish éhtiyajini hés qilghanda, eng téz halda hajetxanigha bérish kérek."]],"保亭":[["保亭是个风景优美的地方。","بويىتېڭ مەنزىرىسى گۈزەل بىر جاي.","boyiténg menzirisi güzel bir jay."]],"修辞":[["这句话运用了巧妙的修辞手法。","بۇ جۈملىدە ماھىر رېتورىكا ئۇسۇلى قوللىنىلغان.","bu jümlide mahir rétorika usuli qollinilghan."]],"保险柜":[["银行的金库配备了多重防护的保险柜。","بانكىنىڭ خەزىنىسى كۆپ قاتلاملىق قوغدىلىدىغان سۇغۇرتا ساندۇقى بىلەن جابدۇلغان.","bankining xezinisi köp qatlamliq qoghdilidighan sughurta sanduqi bilen jabdulghan."]],"信丰县":[["信丰县位于江西省的东南部。","شىنفېڭ ناھىيىسى جياڭشى ئۆلكىسىنىڭ جەنۇبىي شەرقىدە جايلاشقان.","shinféng nahiyisi jyangshi ölkisining jenubiy sherqide jaylashqan."]],"倒果为因":[["他倒果为因，完全误解了事情真相。","ئۇ سەۋەب بىلەن نەتىجىنى ئالماشتۇرۇۋېتىپ، ئىشنىڭ ھەقىقىي ئەھۋالىنى پۈتۈنلەي خاتا چۈشەندى.","u seweb bilen netijini almashturuwétip, ishning heqiqiy ehwalini pütünley xata chüshendi."]],"值得信赖":[["他是一位值得信赖的人。","ئۇ ئىشەنچكە ئەرزىيدىغان ئادەم.","u ishenchke erziydighan adem."]],"傲慢":[["傲慢的态度让他失去朋友。","تەكەببۇر پوزىتسىيەسى ئۇنى دوستلىرىدىن ئايرىۋەتتى.","tekebbur pozitsiyesi uni dostliridin ayriwetti."]],"傲慢与偏见":[["这部小说探讨了傲慢与偏见的主题。","بۇ رومان تەكەببۇرلۇق ۋە خۇراپاتلىق تېمىسىنى مۇھاكىمە قىلىدۇ.","bu roman tekebburluq we xurapatliq témisini muhakime qilidu."]],"充裕":[["今年的收成十分充裕，足以过冬。","بۇ يىللىق ھوسۇل ئىنتايىن مول، قىشتىن ئۆتۈشكە يېتەرلىك.","bu yilliq hosul intayin mol, qishtin ötüshke yéterlik."]],"兀鹰":[["兀鹰的视力极其敏锐。","ئۇدۇرنىڭ كۆرۈش قۇۋۋىتى ناھايىتى ئۆتكۈر.","udurning körüsh quwwiti nahayiti ötkür."]],"优惠券":[["购物时使用优惠券可以节省不少钱。","سېتىۋېلىش چاغىدا ئېتىبار كارتىسىنى ئىشلەتسە كۆپ پۇل تېجىگىلى بولىدۇ.","sétiwélish chaghida étibar kartisini ishletse köp pul téjigili bolidu."]],"全优":[["他的成绩全优，老师很欣慰。","ئۇنىڭ نەتىجىسى ھەممىسى ئەلا، ئوقۇتقۇچى بەك خۇشال بولدى.","uning netijisi hemmisi ela, oqutquchi bek xushal boldi."]],"全南县":[["全南县位于江西省的南部。","چۈەننەن ناھىيىسى جياڭشى ئۆلكىسىنىڭ جەنۇبىدا جايلاشقان.","chüennen nahiyisi jyangshi ölkisining jenubida jaylashqan."]],"兕觥":[["兕觥是古代的一种酒器。","بۇغا تۇياقلىق ھاراق قاچىسى قەدىمكى زامانلاردا ئىشلىتىلگەن بىر خىل ھاراق سايمانلىرىدىن بىرى.","bugha tuyaqliq haraq qachisi qedimki zamanlarda ishlitilgen bir xil haraq saymanliridin biri."]],"全盘":[["全盘考虑问题才能做出正确决策。","مەسىلىنى ئومۇميۈزلۈك ئويلىغاندىلا ئاندىن توغرا قارار چىقارغىلى بولىدۇ.","mesilini omumyüzlük oylighandila andin toghra qarar chiqarghili bolidu."]],"儿戏":[["他小时候总爱玩儿戏。","ئۇ كىچىك ۋاقتىدا ئويۇن ئويناشنى ياخشى كۆرەتتى.","u kichik waqtida oyun oynashni yaxshi köretti."]],"两当县":[["两当县以丰富的自然资源闻名。","لياڭداڭ ناھىيىسى مول تەبىئىي بايلىقلىرى بىلەن داڭلىق.","lyangdang nahiyisi mol tebiiy bayliqliri bilen dangliq."]],"入门课程":[["这是入门课程的基础内容。","بۇ كىرىش دەرسىنىڭ ئاساسىي مەزمۇنى.","bu kirish dersining asasiy mezmuni."]],"八公山":[["八公山位于安徽省，风景优美。","باگۇڭشەن ئەنخۇي ئۆلكىسىدە جايلاشقان، مەنزىرىسى گۈزەل.","bagungshen enxuy ölkiside jaylashqan, menzirisi güzel."]],"八相成道":[["八相成道是佛教关于佛陀成道的过程。","سەككىز باسقۇچلۇق كامالەتكە يېتىش بۇددا دىنىنىڭ بۇددا كامالەتكە يېتىش جەريانى توغرىسىدىكى ئېتىقادىدۇر.","sekkiz basquchluq kamaletke yétish budda dinining budda kamaletke yétish jeryani toghrisidiki étiqadidur."]],"公民表决":[["公民表决决定了政策的方向。","پۇقرالار بېلەت تاشلاش سىياسەتنىڭ يۆنىلىشىنى بەلگىلىدى.","puqralar bélet tashlash siyasetning yönilishini belgilidi."]],"公畜":[["这些公畜被用来繁殖后代。","بۇ ئەركەك چارۋىلار نەسىل ئېلىش ئۈچۈن ئىشلىتىلىدۇ.","bu erkek charwilar nesil élish üchün ishlitilidu."]],"公府":[["古代公府是官员办公和居住的地方。","قەدىمكى زاماندا ئاممىۋى ئىشخانا ئەمەلدارلارنىڭ خىزمەت قىلىدىغان ۋە تۇرىدىغان جايى ئىدى.","qedimki zamanda ammiwi ishxana emeldarlarning xizmet qilidighan we turidighan jayi idi."]],"六碳糖":[["六碳糖是常见糖类。","ئالتە كاربونلۇق شېكەر ئادەتتىكى شېكەر تۈرىدۇر.","alte karbonluq shéker adettiki shéker türidur."]],"典质":[["他拿旧书去典质换钱。","ئۇ كونا كىتابلىرىنى گۆرۈگە قويۇپ پۇل ئالغان.","u kona kitablirini görüge qoyup pul alghan."]],"冤气":[["冤气积聚会引发不幸。","ئەپسۇسلىك ھېسسىياتى يىغىلىپ قالسا بەختسىزلىككە سەۋەب بولىدۇ.","epsuslik héssiyati yighilip qalsa bextsizlikke seweb bolidu."]],"凌蒙初":[["凌蒙初是一位古代文学家。","لىڭ مېڭچۇ قەدىمكى بىر ئەدىب.","ling méngchu qedimki bir edib."]],"冬瓜":[["超市里卖着新鲜的冬瓜。","سۇپېرماركېتتا يېڭى ئۈچەيلەك سېتىلىۋاتىدۇ.","supérmarkétta yéngi ücheylek sétiliwatidu."]],"冬菜":[["冬菜是冬季腌制的咸菜。","قىشلىق كۆكتات قىشتا تۇزلانغان تۇزلام كۆكتات.","qishliq köktat qishta tuzlanghan tuzlam köktat."]],"冷切":[["冷切牛肉口感细腻。","سوغۇق كېسىلگەن كالا گۆشىنىڭ تەمى نەپىس.","soghuq késilgen kala göshining temi nepis."]],"分家":[["兄弟分家后各自独立生活。","ئاكا-ئۇكا ئۆي ئايرىلغاندىن كېيىن ھەر بىرى مۇستەقىل تۇرمۇش كەچۈردى.","aka-uka öy ayrilghandin kéyin her biri musteqil turmush kechürdi."]],"分时":[["分时系统能提高效率。","ۋاقىت بۆلۈش سىستېمىسى ئۈنۈمنى ئاشۇرالايدۇ.","waqit bölüsh sistémisi ünümni ashuralaydu."]],"刑满":[["他刑满释放了。","ئۇ جازا مۇددىتىنى تولدۇرۇپ قويۇپ بېرىلدى.","u jaza mudditini toldurup qoyup bérildi."]],"剖视":[["从剖视角度观察结构更清晰。","قېرىن كېسىش نۇقتىسىدىن قۇرۇلمىنى كۆزەتكەندە تېخىمۇ ئېنىق بولىدۇ.","qérin késish nuqtisidin qurulmini közetkende téximu éniq bolidu."]],"劈脸":[["他劈脸一掌。","ئۇ يۈزىگە بىر شاپىلاق تەگكۈزدى.","u yüzige bir shapilaq tegküzdi."]],"剽悍":[["他剽悍的体魄令人敬佩。","ئۇنىڭ باتۇر بەدەن قۇرۇلۇشى كىشىنى ھەيران قالدۇرىدۇ.","uning batur beden qurulushi kishini heyran qalduridu."]],"利兹":[["利兹是英格兰的重要城市。","لىدس ئىنگلىزىيەنىڭ مۇھىم شەھىرى.","lids ingliziyening muhim shehiri."]],"力挫":[["球队力挫强敌，赢得胜利。","كوماندا كۈچلۈك رەقىبىنى كۈچ بىلەن يېڭىپ، غەلىبە قازاندى.","komanda küchlük reqibini küch bilen yéngip, ghelibe qazandi."]],"加餐":[["加班时，公司会提供加餐。","ئىش ئۈستىدە ئىشلەتكەندە، شىركەت قوشۇمچە تاماق تەمىنلەيدۇ.","ish üstide ishletkende, shirket qoshumche tamaq teminleydu."]],"包打天下":[["他声称能包打天下。","ئۇ پۈتۈن دۇنيانى قاپلاپ ئۇرۇشالايدىغانلىقىنى دەۋا قىلدى.","u pütün dunyani qaplap urushalaydighanliqini dewa qildi."]],"北侧":[["这座建筑的北侧有花园。","بۇ بىنانىڭ شىمالىي تەرىپىدە باغ بار.","bu binaning shimaliy teripide bagh bar."]],"北大":[["北大是中国顶尖的大学之一。","شىمالىي چوڭ ئوقۇتۇش جۇڭگونىڭ ئالدىنقى قاتارلىق ئۇنىۋېرسىتېتلىرىدىن بىرى.","shimaliy chong oqutush junggoning aldinqi qatarliq uniwérsitétliridin biri."]],"北荷兰":[["北荷兰是荷兰的一个省份。","شىمالىي گوللاندىيە گوللاندىيەنىڭ بىر ئۆلكىسى.","shimaliy gollandiye gollandiyening bir ölkisi."]],"升斗":[["一升斗粮食。","بىر لىتىر ئاشلىق.","bir litir ashliq."]],"半场":[["比赛进行到半场时，比分是零比零。","مۇسابىقە يېرىم مەيدانغا كەلگەندە نەتىجە نۆلگە نۆل ئىدى.","musabiqe yérim meydangha kelgende netije nölge nöl idi."]],"北镇满族自治县":[["北镇满族自治县位于辽宁省。","شىمالىي بازار مانجۇ ئاپتونوم ناھىيىسى لياۋنىڭ ئوبلاستىدا جايلاشقان.","shimaliy bazar manju aptonom nahiyisi lyawning oblastida jaylashqan."]],"北欧":[["北欧国家福利完善。","شىمالىي ياۋروپا دۆلەتلىرىنىڭ پاراۋانلىقى مۇكەممەل.","shimaliy yawropa döletlirining parawanliqi mukemmel."]],"南侧":[["建筑的南侧有花园。","بىنانىڭ جەنۇب تەرىپىدە باغ بار.","binaning jenub teripide bagh bar."]],"南大":[["南大是南京大学的简称。","نەندا نەنجىڭ ئۇنىۋېرسىتېتىنىڭ قىسقارتىلما ئاتىلىشى.","nenda nenjing uniwérsitétining qisqartilma atilishi."]],"南安市":[["南安市位于福建省东南部。","نەنئەن شەھىرى فۇجيەن ئۆلكىسىنىڭ جەنۇبىي شەرقىي قىسمىدا جايلاشقان.","nen'en shehiri fujyen ölkisining jenubiy sherqiy qismida jaylashqan."]],"升旗":[["举行庄严的升旗仪式。","تەنتەنىلىك بايراق كۆتۈرۈش مۇراسىمى ئۆتكۈزۈلدى.","tentenilik bayraq kötürüsh murasimi ötküzüldi."]],"千禧年":[["千禧年标志着21世纪的开始。","مىڭ يىللىق يىل 21-ئەسىرنىڭ باشلىنىشىنى بىلدۈرىدۇ.","ming yilliq yil 21-esirning bashlinishini bildüridu."]],"北安市":[["北安市位于中国东北地区。","بېيئەن شەھىرى جۇڭگونىڭ شەرقىي شىمالىي رايونىدا جايلاشقان.","béy'en shehiri junggoning sherqiy shimaliy rayonida jaylashqan."]],"博爱座":[["博爱座是一种交通工具。","مېھىر-مۇھەببەت ئورنى قاتناش قورالى.","méhir-muhebbet orni qatnash qorali."]],"南欧":[["南欧地区气候温和，风景优美。","جەنۇبىي ياۋروپا رايونىنىڭ ئىقلىمى مۆتىدىل، مەنزىرىسى گۈزەل.","jenubiy yawropa rayonining iqlimi mötidil, menzirisi güzel."]],"卡乐星":[["卡乐星是一家知名的快餐连锁品牌。","كارلۇس جۇنىيور مەشھۇر تېز تائام تورى ماركىسى.","karlus juniyor meshhur téz taam tori markisi."]],"厚底鞋":[["她穿了一双厚底鞋。","ئۇ قېلىن تەگلىك ئاياغ كىيىۋالغان.","u qélin teglik ayagh kiyiwalghan."]],"叉尾鸥":[["叉尾鸥在海上飞翔。","قارا بېلىق دېڭىز ئۈستىدە ئۇچىدۇ.","qara béliq déngiz üstide uchidu."]],"参差错落":[["建筑群参差错落，富有层次。","بىنا گۇرۇھى چىگىش-چىگىش بولۇپ، قاتلاملىق.","bina guruhi chigish-chigish bolup, qatlamliq."]],"反斜线":[["路径中使用反斜线。","يولدا قايتۇرما يانتۇ سىزىق ئىشلىتىلىدۇ.","yolda qayturma yantu siziq ishlitilidu."]],"友谊商店":[["友谊商店里有许多纪念品。","دوستلۇق دۇكىنىدا نۇرغۇن ئەسكەرتىش بۇيۇملىرى بار.","dostluq dukinida nurghun eskertish buyumliri bar."]],"友军":[["友军及时赶到，扭转了战局。","دوست قوشۇن ۋاقتىدا يېتىپ كېلىپ، ئۇرۇش ئەھۋالىنى ئۆزگەرتتى.","dost qoshun waqtida yétip kélip, urush ehwalini özgertti."]],"去程":[["去程的旅途很顺利。","بېرىش يولىدىكى سەپەر بەك راۋان بولدى.","bérish yolidiki seper bek rawan boldi."]],"印江县":[["印江县以丰富的矿产资源而闻名。","ئىنجياڭ ناھىيىسى باي مىنېرال بايلىقلىرى بىلەن داڭلىق.","injyang nahiyisi bay minéral bayliqliri bilen dangliq."]],"卵巢窝":[["卵巢位于卵巢窝内。","تۇخۇمدان تۇخۇمدان ئۇۋىسى ئىچىدە جايلاشقان.","tuxumdan tuxumdan uwisi ichide jaylashqan."]],"印加":[["印加文明拥有丰富的文化遗产。","ئىنكا مەدەنىيىتى باي مەدەنىي مىراسقا ئىگە.","inka medeniyiti bay medeniy mirasqa ige."]],"取其精华":[["我们要取其精华，用于实践。","بىز ئۇنىڭ ماھىيىتىنى ئېلىپ ئەمەلىيەتكە قوللىنىشىمىز كېرەك.","biz uning mahiyitini élip emeliyetke qollinishimiz kérek."]],"古塔":[["古塔高耸，是当地的标志性建筑。","قەدىمكى مۇنار ئېگىز بولۇپ، يەرلىكنىڭ بەلگىلىك بىناسى.","qedimki munar égiz bolup, yerlikning belgilik binasi."]],"古昔":[["古昔的景色宁静而美丽。","قەدىمكى زامان مەنزىرىسى ئىنچىكە ۋە گۈزەل ئىدى.","qedimki zaman menzirisi inchike we güzel idi."]],"台江县":[["台江县以丰富的少数民族文化闻名。","تەيجياڭ ناھىيەسى مول ئاز سانلىق مىللەت مەدەنىيىتى بىلەن داڭلىق.","teyjyang nahiyesi mol az sanliq millet medeniyiti bilen dangliq."]],"反脸无情":[["他反脸无情，连朋友都绝交。","ئۇ يۈزىنى ئۆرۈۋېلىپ رەھىمسىزلىك قىلدى، ھەتتا دوستلىرى بىلەنمۇ ئالاقىنى ئۈزدى.","u yüzini örüwélip rehimsizlik qildi, hetta dostliri bilenmu alaqini üzdi."]],"另一半":[["另一半的行程安排在明天进行。","يەنە يېرىمىنىڭ سەپىرى ئەتكەن كۈنى ئېلىپ بېرىلىدۇ.","yene yérimining sepiri etken küni élip bérilidu."]],"吃不了兜着走":[["你惹了他，吃不了兜着走。","ئۇنىڭغا تەگسىڭىز، ئاقىۋىتىگە چىداپ قالالمايسىز.","uninggha tegsingiz, aqiwitige chidap qalalmaysiz."]],"吃喝嫖赌":[["他沉迷吃喝嫖赌。","ئۇ يېيىش-ئىچىش، پاھىشىۋازلىق ۋە قىمارۋازلىققا بېرىلىپ كەتتى.","u yéyish-ichish, pahishiwazliq we qimarwazliqqa bérilip ketti."]],"各执一词":[["双方各执一词，争执不下。","ئىككى تەرەپ ھەر قايسىسى ئۆز سۆزىدە چىڭ تۇرۇپ، تالاش-تارتىش توختىمايدۇ.","ikki terep her qaysisi öz sözide ching turup, talash-tartish toxtimaydu."]],"吊机":[["吊机正在搬运重物。","ئاسما ماشىنا ئېغىر يۈكنى يۆتكەۋاتىدۇ.","asma mashina éghir yükni yötkewatidu."]],"吊铺":[["吊铺是一种悬挂式的床铺设计。","ئاسما كارىۋات ئېسىلما كارىۋات لايىھەسىنىڭ بىر تۈرى.","asma kariwat ésilma kariwat layihesining bir türi."]],"含商咀徵":[["音乐含商咀徵。","مۇزىكا ئەنئەنىۋى ئاھاڭلارنى ئۆز ئىچىگە ئالىدۇ.","muzika en'eniwi ahanglarni öz ichige alidu."]],"吴仁宝":[["吴仁宝是中国著名的企业家。","ۋۇ رېنبائو جۇڭگونىڭ تونۇلغان تىجارەتچىسى.","wu rénbao junggoning tonulghan tijaretchisi."]],"周宣王":[["周宣王是西周时期的君主。","جۇ شۈەنۋاڭ غەربىي جۇ سۇلالىسى دەۋرىنىڭ ھۆكۈمدارى.","ju shüenwang gherbiy ju sulalisi dewrining hökümdari."]],"咒骂":[["他忍不住咒骂了那个对手。","ئۇ رەقىبىگە قارغاشتىن ئۆزىنى تۇتۇپ قالالماي قالدى.","u reqibige qarghashtin özini tutup qalalmay qaldi."]],"告示":[["告示牌上写着禁止入内的字样。","ئۇقتۇرۇش تاختىسىدا كىرىش مەنئىي قىلىنغانلىقى يېزىلغان.","uqturush taxtisida kirish men'iy qilinghanliqi yézilghan."]],"商家":[["商家们积极参与了这次促销活动。","سودىگەرلەر بۇ قېتىملىق ئىلگىرى سۈرۈش پائالىيىتىگە ئاكتىپ قاتناشتى.","sodigerler bu qétimliq ilgiri sürüsh paaliyitige aktip qatnashti."]],"哈马尔":[["哈马尔是挪威的滑雪胜地。","ھامار نورۋېگىيەنىڭ چاڭغا تېيىلىش مەنزىلگاھى.","hamar norwégiyening changgha téyilish menzilgahi."]],"商丘市":[["商丘市位于河南。","شاڭچيۇ شەھىرى خېنەن ئۆلكىسىدە جايلاشقان.","shangchyu shehiri xénen ölkiside jaylashqan."]],"喜山白眉朱雀":[["这种鸟叫喜山白眉朱雀。","بۇ خىل قۇش خۇشال تاغ ئاق قاش قىزىلگۈمى دەپ ئاتىلىدۇ.","bu xil qush xushal tagh aq qash qizilgümi dep atilidu."]],"喜山点翅朱雀":[["喜山点翅朱雀羽毛鲜艳。","خۇشال تاغ چېكىت قانات قىزىلگۈمىنىڭ پەيلىرى پارقىراق.","xushal tagh chékit qanat qizilgümining peyliri parqiraq."]],"丧家之犬":[["他如今成了丧家之犬，无家可归。","ئۇ ھازىر ئۆيىدىن ئايرىلىپ، باشپاناھسىز قالدى.","u hazir öyidin ayrilip, bashpanahsiz qaldi."]],"丧德":[["他丧德败行，令人不齿。","ئۇ ئەخلاقسىزلىق قىلىپ، كىشىلەرنىڭ يىرگىنىشىگە ئۇچرىدى.","u exlaqsizliq qilip, kishilerning yirginishige uchridi."]],"丧气话":[["别再说丧气话，要振作起来！","ئەمدى روھىڭىزنى چۈشۈرىدىغان گەپلەرنى دېمەڭ، ئۆزىڭىزنى تۇتۇڭ!","emdi rohingizni chüshüridighan geplerni démeng, özingizni tutung!"]],"喜群游":[["一群朋友在湖边喜群游，尽情玩耍。","بىر توپ دوستلار كۆل بويىدا خۇشال سەيلە قىلىپ، كۆڭۈل ئېچىپ ئوينىدى.","bir top dostlar köl boyida xushal seyle qilip, köngül échip oynidi."]],"嘉峪关市":[["嘉峪关市地处西北，气候干燥。","جىيايۈگۈەن شەھىرى شىمالىي غەربتە جايلاشقان بولۇپ، ھاۋاسى قۇرغاق.","jiyayügüen shehiri shimaliy gherbte jaylashqan bolup, hawasi qurghaq."]],"噶伦":[["噶伦是传统服饰。","گالۇن ئەنئەنىۋى كىيىم-كېچەكتۇر.","galun en'eniwi kiyim-kéchektur."]],"嘶嘶声":[["传来一阵嘶嘶声。","بىر مەھەل غىژىلداپ ئاۋاز ئاڭلاندى.","bir mehel ghizhildap awaz anglandi."]],"单身贵族":[["单身贵族追求高品质的独立生活。","بويتاق ئاقسۆڭەكلەر يۇقىرى سۈپەتلىك مۇستەقىل تۇرمۇشنى ئىزدەيدۇ.","boytaq aqsöngekler yuqiri süpetlik musteqil turmushni izdeydu."]],"喵星人":[["这只喵星人特别可爱。","بۇ مۈشۈك ئالاھىدە يېقىملىق.","bu müshük alahide yéqimliq."]],"喹啉":[["喹啉是一种重要的有机化合物。","كىنولىن مۇھىم بىر ئورگانىك بىرىكمە.","kinolin muhim bir organik birikme."]],"四大须生":[["四大须生是京剧中的杰出演员。","تۆت چوڭ شۈشېڭ جىڭجۇدىكى كۆزگە چېلىقارلىق ئارتىستلاردۇر.","töt chong shüshéng jingjudiki közge chéliqarliq artistlardur."]],"因利乘便":[["他因利乘便，占了不少便宜。","ئۇ پۇرسەتتىن پايدىلىنىپ، كۆپ مەنپەئەت ئالدى.","u pursettin paydilinip, köp menpeet aldi."]],"国界线":[["这条国界线划分了两个国家的领土。","بۇ دۆلەت چېگرىسى ئىككى دۆلەتنىڭ زېمىنىنى ئايرىغان.","bu dölet chégrisi ikki döletning zéminini ayrighan."]],"国际清算银行":[["国际清算银行是各国央行合作的重要平台。","خەلقئارا ھېسابات كېلىشىم بانكىسى ھەر قايسى دۆلەت مەركىزىي بانكىلىرى ھەمكارلىشىدىغان مۇھىم سۇپىدۇر.","xelq'ara hésabat kélishim bankisi her qaysi dölet merkiziy bankiliri hemkarlishidighan muhim supidur."]],"国际电话":[["国际电话连接不同国家。","خەلقئارا تېلېفون ئوخشىمىغان دۆلەتلەرنى تۇتاشتۇرىدۇ.","xelq'ara téléfon oxshimighan döletlerni tutashturidu."]],"围护":[["围护结构能增强建筑物的安全性。","قورشاش قۇرۇلمىسى بىنانىڭ بىخەتەرلىكىنى كۈچەيتەلەيدۇ.","qorshash qurulmisi binaning bixeterlikini kücheyteleydu."]],"圆顶":[["教堂的圆顶很高。","چېركاۋنىڭ يۇمىلاق گۈمبىزى ئىنتايىن ئېگىز.","chérkawning yumilaq gümbizi intayin égiz."]],"土坯":[["土坯是传统建筑的材料之一。","ساپال كېسەك ئەنئەنىۋى قۇرۇلۇش ماتېرىياللىرىنىڭ بىرى.","sapal kések en'eniwi qurulush matériyallirining biri."]],"垣曲县":[["垣曲县位于山西省西南部。","يۈەنچۈ ناھىيىسى شەنشى ئۆلكىسىنىڭ جەنۇبىي غەربىي قىسمىدا جايلاشقان.","yüenchü nahiyisi shenshi ölkisining jenubiy gherbiy qismida jaylashqan."]],"埃克托":[["埃克托是一位著名的音乐家。","ئېكتور مەشھۇر بىر مۇزىكانت.","éktor meshhur bir muzikant."]],"基本利率":[["基本利率由央行设定。","ئاساسىي ئۆسۈم نىسبىتى مەركىزىي بانكا تەرىپىدىن بەلگىلىنىدۇ.","asasiy ösüm nisbiti merkiziy banka teripidin belgilinidu."]],"基本粒子":[["原子由基本粒子构成。","ئاتوم ئاساسىي زەررىچىلەردىن تەركىب تاپقان.","atom asasiy zerrichilerdin terkib tapqan."]],"执迷":[["他执迷于自己的错误观点，不愿接受批评。","ئۇ ئۆزىنىڭ خاتا كۆز قارىشىغا بېرىلىپ كەتتى، تەنقىدنى قوبۇل قىلىشقا ئۇنىمايدۇ.","u özining xata köz qarishigha bérilip ketti, tenqidni qobul qilishqa unimaydu."]],"垂直尾翼":[["垂直尾翼对飞机的稳定性至关重要。","تىك قۇيرۇق ئايروپىلاننىڭ مۇقىملىقى ئۈچۈن ئىنتايىن مۇھىم.","tik quyruq ayropilanning muqimliqi üchün intayin muhim."]],"基础问题":[["基础问题是学习中的首要难题。","ئاساسىي مەسىلە ئۆگىنىشتىكى ئەڭ مۇھىم قىيىنچىلىقتۇر.","asasiy mesile öginishtiki eng muhim qiyinchiliqtur."]],"塞尔维亚和黑山":[["塞尔维亚和黑山曾是南斯拉夫的成员国。","سېربىيە ۋە قارا تاغ يۇگوسلاۋىيەنىڭ ئەزالىرى بولۇپ قالغان.","sérbiye we qara tagh yugoslawiyening ezaliri bolup qalghan."]],"垦殖":[["垦殖需要多年的努力。","كېڭەيتىپ تېرىقچىلىق قىلىش كۆپ يىللىق تىرىشچانلىقنى تەلەپ قىلىدۇ.","kéngeytip tériqchiliq qilish köp yilliq tirishchanliqni telep qilidu."]],"壮实":[["他身材壮实，看起来很有力量。","ئۇنىڭ بەدەنى پۇختا، كۈچلۈك كۆرۈنىدۇ.","uning bedeni puxta, küchlük körünidu."]],"寿命不长":[["这种植物的寿命不长，只有几年。","بۇ ئۆسۈملۈكنىڭ ئۆمرى ئۇزۇن ئەمەس، پەقەت بىر نەچچە يىل.","bu ösümlükning ömri uzun emes, peqet bir nechche yil."]],"寿丰乡":[["寿丰乡位于山区地带。","مۇبارەك مول يېزىسى تاغلىق رايوندا جايلاشقان.","mubarek mol yézisi taghliq rayonda jaylashqan."]],"外向型":[["外向型经济依赖出口。","سىرتقا قارىغان تىپتىكى ئىقتىساد ئېكسپورتقا تايىنىدۇ.","sirtqa qarighan tiptiki iqtisad éksportqa tayinidu."]],"外商直接投资":[["外商直接投资促进了发展。","سىرتقى سودىگەرلەرنىڭ بىۋاسىتە مەبلىغى تەرەققىياتنى ئىلگىرى سۈردى.","sirtqi sodigerlerning biwasite meblighi tereqqiyatni ilgiri sürdi."]],"坠子":[["坠子是传统乐器的一部分。","زەنجىرسىمان زىننەت بۇيۇمى ئەنئەنىۋى چالغۇ ئەسۋابىنىڭ بىر قىسمى.","zenjirsiman zinnet buyumi en'eniwi chalghu eswabining bir qismi."]],"多模块":[["系统采用多模块设计，便于扩展。","سىستېما كۆپ مودۇللۇق لايىھەنى قوللىنىدۇ، كېڭەيتىشكە ئاسان.","sistéma köp modulluq layiheni qollinidu, kéngeytishke asan."]],"多氯联苯":[["多氯联苯是一种有毒的化学物质。","كۆپ خلورلۇق بىفېنىل بىر خىل زەھەرلىك خىمىيەلىك ماددىدۇر.","köp xlorluq bifénil bir xil zeherlik ximiyelik maddidur."]],"大树莺":[["大树莺的歌声清脆悦耳。","چوڭ دەرەخ چىمچىقىنىڭ ناخشىسى سۈزۈك ۋە يېقىملىق.","chong derex chimchiqining naxshisi süzük we yéqimliq."]],"大有人在":[["这里大有人在，热闹非凡。","بۇ يەردە كىشىلەر ناھايىتى كۆپ، ئىنتايىن ئاۋات.","bu yerde kishiler nahayiti köp, intayin awat."]],"大英联合王国":[["大英联合王国由四个国家组成。","بۈيۈك بىرلەشمە پادىشاھلىق تۆت دۆلەتتىن تەركىب تاپقان.","büyük birleshme padishahliq töt dölettin terkib tapqan."]],"大号":[["他注册了一个新的大号。","ئۇ يېڭى بىر چوڭ نومۇرلۇق تېلېفون تىزىملاتتى.","u yéngi bir chong nomurluq téléfon tizimlatti."]],"大量生产":[["工厂实现了大量生产。","زاووت كۆپ مىقداردا ئىشلەپچىقىرىشنى ئەمەلگە ئاشۇردى.","zaoot köp miqdarda ishlepchiqirishni emelge ashurdi."]],"大阿姨":[["大阿姨来家里做客。","چوڭ ئاچا ئۆيگە مېھمان بولۇشقا كەلدى.","chong acha öyge méhman bolushqa keldi."]],"天作之合":[["他们真是天作之合，令人羡慕。","ئۇلار ھەقىقەتەن خۇدا تەرىپىدىن يارىتىلغان جۈپ، كىشىنى ھەۋەس قىلدۇرىدۇ.","ular heqiqeten xuda teripidin yaritilghan jüp, kishini hewes qilduridu."]],"天方":[["天方一词多用于地名。","«تەڭرىپەن» دېگەن سۆز كۆپىنچە يەر ناملىرىدا ئىشلىتىلىدۇ.","«tengripen» dégen söz köpinche yer namlirida ishlitilidu."]],"大盘鸡":[["大盘鸡是一道深受人们喜爱的川菜。","داشاڭجى تائامى كىشىلەر ياخشى كۆرىدىغان سىچۈەن تائاملىرىنىڭ بىرى.","dashangji taami kishiler yaxshi köridighan sichüen taamlirining biri."]],"大谈特谈":[["他大谈特谈政治。","ئۇ سىياسەت توغرىسىدا چوڭ-چوڭ سۆزلەپ كەتتى.","u siyaset toghrisida chong-chong sözlep ketti."]],"失态":[["他在公众场合突然失态。","ئۇ ئاممىۋى سورۇندا تۇيۇقسىز ئۆزىنى تۇتۇۋېلالمىدى.","u ammiwi sorunda tuyuqsiz özini tutuwélalmidi."]],"奉为圭臬":[["人们奉为圭臬的准则。","كىشىلەر ئۇنى ئۆلچەم قىلىپ قوبۇل قىلىدۇ.","kishiler uni ölchem qilip qobul qilidu."]],"契卡":[["契卡是苏联早期的秘密警察机构。","چېكا سوۋېت ئىتتىپاقىنىڭ دەسلەپكى مەزگىلدىكى مەخپىي ساقچى ئورگىنى ئىدى.","chéka sowét ittipaqining deslepki mezgildiki mexpiy saqchi orgini idi."]],"女娃":[["这个女娃特别可爱。","بۇ قىزچاق بەك ئوماق.","bu qizchaq bek omaq."]],"妖娆":[["她舞姿妖娆动人。","ئۇنىڭ ئۇسسۇلى جادۇگەرلەرچە مەھلىيا قىلارلىق.","uning ussuli jadugerlerche mehliya qilarliq."]],"妄说":[["他的妄说让团队陷入混乱之中。","ئۇنىڭ ئاساسسىز سۆزلىرى كوماندىنى قالايمىقانچىلىققا چۆمدۈردى.","uning asassiz sözliri komandini qalaymiqanchiliqqa chömdürdi."]],"威妥玛拼法":[["威妥玛拼法很常见。","ۋېيدۇما ئىملا ئۇسۇلى ناھايىتى كۆپ ئۇچرايدۇ.","wéyduma imla usuli nahayiti köp uchraydu."]],"姨娘":[["姨娘年轻时是个很能干的人。","تاغا ئاچا ياش ۋاقتىدا ناھايىتى قابىلىيەتلىك ئادەم ئىدى.","tagha acha yash waqtida nahayiti qabiliyetlik adem idi."]],"侄女婿":[["侄女婿对家庭非常体贴。","جىيەنۈي ئايالى ئائىلىسىگە ئىنتايىن كۆيۈمچان.","jiyenüy ayali ailisige intayin köyümchan."]],"姬滨鹬":[["姬滨鹬是一种沿海栖息的鸟类。","جىيەنبىنيۇ قىرغاقتا ياشايدىغان بىر خىل قۇش.","jiyenbinyu qirghaqta yashaydighan bir xil qush."]],"婆家":[["她嫁到婆家后很适应。","ئۇ قەينانا ئۆيىگە ياتلىق بولغاندىن كېيىن ياخشى ماسلاشتى.","u qeynana öyige yatliq bolghandin kéyin yaxshi maslashti."]],"婉妙":[["她的表演婉妙动人。","ئۇنىڭ ئىپادىسى نازۇك ۋە تەسىرلىك.","uning ipadisi nazuk we tesirlik."]],"子长县":[["子长县位于陕西省北部。","تارماق چاڭ ناھىيىسى شەنشى ئۆلكىسىنىڭ شىمالىدا جايلاشقان.","tarmaq chang nahiyisi shenshi ölkisining shimalida jaylashqan."]],"孑然一身":[["他孑然一身来到这座城市。","ئۇ يالغۇز ھالەتتە بۇ شەھەرگە كەلدى.","u yalghuz halette bu sheherge keldi."]],"孕童":[["孕童教育备受关注。","ھامىلىدار بالىلار مائارىپىغا كۆپ دىققەت قىلىنماقتا.","hamilidar balilar maaripigha köp diqqet qilinmaqta."]],"季后赛":[["季后赛竞争激烈。","پەسىل ئاخىرىدىكى مۇسابىقە رەقابىتى كەسكىن.","pesil axiridiki musabiqe reqabiti keskin."]],"孤拔":[["孤拔将军在战争中英勇牺牲。","يالغۇز قوماندان ئۇرۇشتا قەھرىمانلارچە شېھىت بولدى.","yalghuz qomandan urushta qehrimanlarche shéhit boldi."]],"安平区":[["安平区是石家庄市的一部分。","ئەنپىڭ رايونى شىجياجۇاڭ شەھىرىنىڭ بىر قىسمىدۇر.","enping rayoni shijyajuang shehirining bir qismidur."]],"安龙":[["安龙是贵州省的一个县。","ئەنلۇڭ گۈيژۇ ئۆلكىسىدىكى بىر ناھىيە.","enlung güyzhu ölkisidiki bir nahiye."]],"宗教徒":[["宗教徒们积极参与每周的礼拜活动。","دىنغا ئېتىقاد قىلغۇچىلار ھەپتىلىك ئىبادەت پائالىيەتلىرىگە ئاكتىپ قاتنىشىدۇ.","dingha étiqad qilghuchilar heptilik ibadet paaliyetlirige aktip qatnishidu."]],"家鸦":[["家鸦的叫声很刺耳。","ئۆي قاغىسىنىڭ ئاۋازى بەك ئۆتكۈر.","öy qaghisining awazi bek ötkür."]],"富富有余":[["他收入丰厚，生活富富有余。","ئۇنىڭ كىرىمى مول، تۇرمۇشى باياشات.","uning kirimi mol, turmushi bayashat."]],"富贵竹":[["富贵竹寓意吉祥，常被用来装饰家居。","بايلىق بامبۇكى بەخت-سائادەتنى ئىپادىلەيدۇ، كۆپىنچە ئۆي-ئىمارەتلەرنى بېزەشكە ئىشلىتىلىدۇ.","bayliq bambuki bext-saadetni ipadileydu, köpinche öy-imaretlerni bézeshke ishlitilidu."]],"封网":[["系统自动封网了。","سىستېما ئاپتوماتىك تورنى چەكلىدى.","sistéma aptomatik torni cheklidi."]],"封邑":[["古代封邑制度盛行。","قەدىمكى دەۋردە فېڭيى تۈزۈمى ئومۇملاشقان.","qedimki dewrde féngyi tüzümi omumlashqan."]],"射阳县":[["射阳县位于江苏省的东南部。","شېياڭ ناھىيىسى جياڭسۇ ئۆلكىسىنىڭ جەنۇبىي شەرقىدە جايلاشقان.","shéyang nahiyisi jyangsu ölkisining jenubiy sherqide jaylashqan."]],"专属经济区":[["专属经济区是沿海国家管辖的海洋区域。","مەخسۇس ئىقتىسادىي رايون دېڭىز بويى دۆلەتلەر باشقۇرىدىغان دېڭىز رايونىدۇر.","mexsus iqtisadiy rayon déngiz boyi döletler bashquridighan déngiz rayonidur."]],"对称性":[["这个图形具有完美的对称性。","بۇ گرافىكا مۇكەممەل سىممېترىيىلىك خۇسۇسىيەتكە ئىگە.","bu grafika mukemmel simmétriyilik xususiyetke ige."]],"对立面":[["双方形成了鲜明的对立面。","ئىككى تەرەپ ئېنىق قارمۇقارشى تەرەپ شەكىللەندۈردى.","ikki terep éniq qarmuqarshi terep shekillendürdi."]],"对等":[["两国建立了平等对等的外交关系。","ئىككى دۆلەت باراۋەر ۋە تەڭ قاتناشقان دىپلوماتىيە مۇناسىۋىتى ئورناتتى.","ikki dölet barawer we teng qatnashqan diplomatiye munasiwiti ornatti."]],"小弟":[["小弟在团队里总是听从安排。","كىچىك ئىنى ئەترەتتە ھەمىشە ئورۇنلاشتۇرۇشقا بويسۇنىدۇ.","kichik ini etrette hemishe orunlashturushqa boysunidu."]],"尤里斯·伊文思":[["尤里斯·伊文思是纪录片大师。","يۇرىس ئىۋېنس ھۆججەتلىك فىلىم ئۇستىسى.","yuris iwéns höjjetlik filim ustisi."]],"尼安德塔人":[["尼安德塔人是早期人类之一。","نىئاندرتال ئادەم ئەڭ ئەرتىكى ئىنسانلارنىڭ بىرىدۇر.","niandrtal adem eng ertiki insanlarning biridur."]],"小鬟":[["古代的小鬟负责梳发。","قەدىمكى كىچىك قىز چاچ تارايتتى.","qedimki kichik qiz chach taraytti."]],"小鸟":[["这只小鸟在树枝上唱歌。","بۇ كىچىك قۇش شاختا ناخشا ئېيتىدۇ.","bu kichik qush shaxta naxsha éytidu."]],"小熊猫":[["小熊猫是一种珍稀的哺乳动物。","كىچىك پاندا ناھايىتى ئاز ئۇچرايدىغان سۈت ئەمگۈچى ھايۋان.","kichik panda nahayiti az uchraydighan süt emgüchi haywan."]],"少校":[["他是一名少校军官。","ئۇ بىر مايور ئوفىتسېر.","u bir mayor ofitsér."]],"尿意":[["强烈的尿意让他无法集中注意力。","كۈچلۈك سۈيدۈك ئىستىكى ئۇنىڭ دىققىتىنى مەركەزلەشتۈرەلمىدى.","küchlük süydük istiki uning diqqitini merkezleshtürelmidi."]],"小钢球":[["小钢球被用来测试机器的精度。","كىچىك پولات شارچە ماشىنىنىڭ ئېنىقلىقىنى سىناش ئۈچۈن ئىشلىتىلىدۇ.","kichik polat sharche mashinining éniqliqini sinash üchün ishlitilidu."]],"尖细":[["她的声音尖细，听起来很清脆。","ئۇنىڭ ئاۋازى ئىنچىكە، ئاڭلىغاندا ئىنتايىن سۈزۈك.","uning awazi inchike, anglighanda intayin süzük."]],"尸骨":[["尸骨在考古发掘中被发现。","سۆڭەك ئارخېئولوگىيەلىك قېزىشتا بايقالدى.","söngek arxéologiyelik qézishta bayqaldi."]],"山寨货":[["山寨货是指仿冒品牌的产品。","شەنزاي خو باشقا ماركىلارنىڭ مەھسۇلاتلىرىغا تەقلىد قىلىنغان مەھسۇلاتلارنى كۆرسىتىدۇ.","shenzay xo bashqa markilarning mehsulatlirigha teqlid qilinghan mehsulatlarni körsitidu."]],"局地":[["局地天气变化多端。","يەرلىك ھاۋارايى ئۆزگىرىشى كۆپ خىل.","yerlik hawarayi özgirishi köp xil."]],"山梁":[["山梁是两座山之间的低地。","شاڭلياڭ ئىككى تاغ ئارىسىدىكى پەسلىكتۇر.","shanglyang ikki tagh arisidiki pesliktur."]],"峨嵋拳":[["峨嵋拳是一种武术。","ئېمېي مۇشتى بىر خىل ۋۇشۇ.","éméy mushti bir xil wushu."]],"峨眉山":[["峨眉山是佛教圣地。","ئېمېي تېغى بۇددا دىنىنىڭ مۇقەددەس جايى.","éméy téghi budda dinining muqeddes jayi."]],"岛鸫":[["岛鸫是一种生活在岛上的鸟类。","ئارال تۇردى ئارالدا ياشايدىغان بىر خىل قۇش.","aral turdi aralda yashaydighan bir xil qush."]],"川褐头山雀":[["川褐头山雀是一种小型鸟类。","چۈەن قوڭۇر باشلىق تاغ چىمچىقى كىچىك تىپتىكى قۇش تۈرى.","chüen qongur bashliq tagh chimchiqi kichik tiptiki qush türi."]],"峄城区":[["峄城区是当地重要的经济中心。","يىچېڭ رايونى يەرلىكنىڭ مۇھىم ئىقتىساد مەركىزى.","yichéng rayoni yerlikning muhim iqtisad merkizi."]],"川汇区":[["川汇区近年来经济快速发展。","چۈەنخۇي رايونى يېقىنقى يىللاردا ئىقتىسادى تېز تەرەققىي قىلدى.","chüenxuy rayoni yéqinqi yillarda iqtisadi téz tereqqiy qildi."]],"工兵":[["工兵负责战场的工程作业。","ئىنژېنېر ئەسكەرلەر جەڭ مەيدانىدىكى قۇرۇلۇش خىزمىتىگە مەسئۇل.","inzhénér eskerler jeng meydanidiki qurulush xizmitige mes'ul."]],"左首":[["船长的左首站着几位军官。","كېمە كاپىتانىنىڭ سول تەرىپىدە بىر قانچە ئوفىتسېر تۇراتتى.","kéme kapitanining sol teripide bir qanche ofitsér turatti."]],"己见":[["他的己见与团队意见相左。","ئۇنىڭ شەخسىي پىكرى گۇرۇپپا پىكرى بىلەن زىددىيەتتە.","uning shexsiy pikri guruppa pikri bilen ziddiyette."]],"巫医":[["巫医结合草药与仪式进行治疗。","ۋۇيى دورا ئۆسۈملۈكلىرى بىلەن مۇراسىمنى بىرلەشتۈرۈپ داۋالايدۇ.","wuyi dora ösümlükliri bilen murasimni birleshtürüp dawalaydu."]],"巴林右":[["巴林右旗是蒙古的旗。","بەھرەين ئوڭ بېيقى موڭغۇلنىڭ بىر بېيقى.","behreyn ong béyqi mongghulning bir béyqi."]],"巨擘":[["巨擘企业引领行业潮流。","گىگانت شىركەت ساھە ئېقىمىنى يېتەكلەيدۇ.","gigant shirket sahe éqimini yétekleydu."]],"巧固球":[["这个巧固球设计得非常巧妙。","بۇ ماھىر توپ لايىھەسى ئىنتايىن ماھىرانە قىلىنغان.","bu mahir top layihesi intayin mahirane qilinghan."]],"巧家县":[["巧家县拥有丰富的矿产资源。","ماھىر ئائىلە ناھىيىسى باي مىنېرال بايلىقلارغا ئىگە.","mahir aile nahiyisi bay minéral bayliqlargha ige."]],"巴马干酪":[["巴马干酪以其独特的风味而闻名。","باما پىشلاقچىلىقى ئۆزىگە خاس تەمى بىلەن تونۇلغان.","bama pishlaqchiliqi özige xas temi bilen tonulghan."]],"巴彦淖尔":[["巴彦淖尔是内蒙古的一个盟。","باياننۇر ئىچكى موڭغۇلنىڭ بىر ئايمىقى.","bayannur ichki mongghulning bir aymiqi."]],"巴斯克":[["巴斯克地区以美食闻名。","باسك رايونى تائاملىرى بىلەن تونۇلغان.","bask rayoni taamliri bilen tonulghan."]],"幽门螺旋菌":[["幽门螺旋菌是常见病菌。","پىلورۇس ھېلىكوباكتېر بىكتېرىيىسى كۆپ ئۇچرايدىغان بىكتېرىيە.","pilorus hélikobaktér biktériyisi köp uchraydighan biktériye."]],"底比斯":[["底比斯是古代埃及的重要城市之一。","تىبە قەدىمكى مىسىرنىڭ مۇھىم شەھەرلىرىنىڭ بىرىدۇر.","tibe qedimki misirning muhim sheherlirining biridur."]],"底肥":[["底肥是种植前施加在土壤中的肥料。","ئاساس ئوغۇت تېرىشتىن ئىلگىرى تۇپراققا سېلىنىدىغان ئوغۇتتۇر.","asas oghut térishtin ilgiri tupraqqa sélinidighan oghuttur."]],"平权":[["平权原则应适用于所有人。","تەڭ ھوقۇقلۇق پرىنسىپى ھەممە كىشىگە قوللىنىلىشى كېرەك.","teng hoquqluq prinsipi hemme kishige qollinilishi kérek."]],"广告主":[["广告主负责提供广告内容。","ئېلان ئىگىسى ئېلان مەزمۇنىنى تەمىنلەشكە مەسئۇل.","élan igisi élan mezmunini teminleshke mes'ul."]],"廷巴克图":[["廷巴克图是马里著名的古城。","تىمبۇكتۇ مالىنىڭ مەشھۇر قەدىمىي شەھىرى.","timbuktu malining meshhur qedimiy shehiri."]],"建三江":[["建三江位于黑龙江省东部。","جەنسەنجياڭ خېيلۇڭجياڭ ئۆلكىسىنىڭ شەرقىي قىسمىدا جايلاشقان.","jensenjyang xéylungjyang ölkisining sherqiy qismida jaylashqan."]],"弗吉尼亚":[["弗吉尼亚是美国的一个州。","ۋىرگىنىيە ئامېرىكىنىڭ بىر شىتاتى.","wirginiye amérikining bir shitati."]],"强横":[["他为人强横，令人难以接近。","ئۇ كىشىلىك جەھەتتە كۈچلۈك، يېقىنلىشىش قىيىن.","u kishilik jehette küchlük, yéqinlishish qiyin."]],"引桥":[["这座引桥连接了两岸的道路。","بۇ كۆۋرۈك ئىككى قىرغاقنىڭ يوللىرىنى تۇتاشتۇرىدۇ.","bu köwrük ikki qirghaqning yollirini tutashturidu."]],"影壁":[["影壁装饰得很精美。","سايە تام بەك نەپىس بېزەلگەن.","saye tam bek nepis bézelgen."]],"彭泽":[["彭泽县历史悠久，文化深厚。","پېڭ زې ناھىيىسىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى چوڭقۇر.","péng zé nahiyisining tarixi uzun, medeniyiti chongqur."]],"后盾":[["他的家庭是他的坚强后盾。","ئۇنىڭ ئائىلىسى ئۇنىڭ مۇستەھكەم كەينى تىرىكى.","uning ailisi uning mustehkem keyni tiriki."]],"心里有数":[["我心里有数，不会出错。","كۆڭلۈمدە سان بار، خاتالىق چىقمايدۇ.","könglümde san bar, xataliq chiqmaydu."]],"快攻":[["快攻战术很有效。","تېز ھۇجۇم تاكتىكىسى ئىنتايىن ئۈنۈملۈك.","téz hujum taktikisi intayin ünümlük."]],"心宿二":[["心宿二是夜空中最亮的恒星之一。","شىنشيۇئەر ئىككى كېچىلىك ئاسماندىكى ئەڭ يورۇق يۇلتۇزلارنىڭ بىرى.","shinshyuer ikki kéchilik asmandiki eng yoruq yultuzlarning biri."]],"性别比":[["性别比失衡需关注。","جىنس نىسبىتىنىڭ تەڭپۇڭسىزلىقىغا دىققەت قىلىش كېرەك.","jins nisbitining tengpungsizliqigha diqqet qilish kérek."]],"心理防线":[["心理防线是抵御外界压力的重要屏障。","پسىخولوگىيەلىك مۇداپىئە سېپى سىرتقى دۇنيانىڭ بېسىمىغا تاقابىل تۇرىدىغان مۇھىم توساقتۇر.","psixologiyelik mudapie sépi sirtqi dunyaning bésimigha taqabil turidighan muhim tosaqtur."]],"心神专注":[["他心神专注，完成了画作。","ئۇ روھىنى مەركەزلەشتۈرۈپ، رەسىمنى تاماملىدى.","u rohini merkezleshtürüp, resimni tamamlidi."]],"心结":[["他解开了多年的心结。","ئۇ كۆپ يىللىق كۆڭۈل تۈگۈنىنى يەشتى.","u köp yilliq köngül tügünini yeshti."]],"恢恢有余":[["他的才华恢恢有余，令人赞叹。","ئۇنىڭ تالانتى مول-ھېسابسىز، كىشىنى ھەيران قالدۇرىدۇ.","uning talanti mol-hésabsiz, kishini heyran qalduridu."]],"悸动":[["她的内心因他而悸动。","ئۇنىڭ كۆڭلى ئۇنىڭ ئۈچۈن لەرزىگە كەلدى.","uning köngli uning üchün lerzige keldi."]],"恶梦":[["昨晚做了个可怕的恶梦。","تۈنۈگۈن كېچىدە قورقۇنچلۇق چۈش كۆردۈم.","tünügün kéchide qorqunchluq chüsh kördüm."]],"恶意中伤":[["恶意中伤会毁掉名誉。","يامان نىيەت بىلەن تۆھمەت قىلىش نامۇسىنى بۇزىدۇ.","yaman niyet bilen töhmet qilish namusini buzidu."]],"恶魔城":[["恶魔城是恐怖故事中的经典场景。","شەيتانلار شەھىرى قورقۇنچلۇق ھېكايىلەردىكى كلاسسىك مەنزىرە.","sheytanlar shehiri qorqunchluq hékayilerdiki klassik menzire."]],"惠子":[["惠子是一位著名的哲学家。","خۇيزى مەشھۇر بىر پەلسەپىشۇناس ئىدى.","xuyzi meshhur bir pelsepishunas idi."]],"悖逆":[["他公然悖逆了父亲的命令。","ئۇ ئاتىسىنىڭ بۇيرۇقىغا ئوچۇق خىلاپلىق قىلدى.","u atisining buyruqigha ochuq xilapliq qildi."]],"爱克斯射线":[["爱克斯射线能穿透物体内部。","رېنتگېن نۇرى جىسىملارنىڭ ئىچكى قىسمىدىن ئۆتەلەيدۇ.","réntgén nuri jisimlarning ichki qismidin öteleydu."]],"爱得死去活来":[["他爱得死去活来，无法自拔。","ئۇ سۆيگۈسىدە ئۆلۈپ-قالغۇدەك، ئۆزىنى تۇتۇۋالالمايدۇ.","u söygüside ölüp-qalghudek, özini tutuwalalmaydu."]],"惨变":[["局势突然发生了惨变。","ئەھۋال تۇيۇقسىز ئېچىنىشلىق ئۆزگىرىشكە ئۇچرىدى.","ehwal tuyuqsiz échinishliq özgirishke uchridi."]],"庆尚北道":[["庆尚北道是韩国的重要地区。","چىڭشاڭ شىمالىي يولى كورېيەنىڭ مۇھىم رايونىدۇر.","chingshang shimaliy yoli koréyening muhim rayonidur."]],"庆尚南道":[["庆尚南道以美丽的海滩著称。","چىڭشاڭ جەنۇبىي يولى گۈزەل دېڭىز ساھىللىرى بىلەن داڭلىقتۇر.","chingshang jenubiy yoli güzel déngiz sahilliri bilen dangliqtur."]],"悬停":[["无人机在空中悬停不动。","ئۇچقۇچىسىز ئايروپىلان ھاۋادا ھەرىكەتسىز ئېسىلىپ تۇردى.","uchquchisiz ayropilan hawada heriketsiz ésilip turdi."]],"或将":[["会议或将推迟到下周举行。","يىغىن بەلكىم كېلەر ھەپتىگە كېچىكتۈرۈلۈشى مۇمكىن.","yighin belkim kéler heptige kéchiktürülüshi mumkin."]],"户均":[["户均面积较小。","ئۆي باشىغا توغرا كېلىدىغان كۆلەم بىر قەدەر كىچىك.","öy bashigha toghra kélidighan kölem bir qeder kichik."]],"扒搂":[["她扒搂着被子，不肯睡觉。","ئۇ يوتقاننى تارتىپ، ياتمىدى.","u yotqanni tartip, yatmidi."]],"才思":[["她的才思敏捷，总能妙语连珠。","ئۇنىڭ تالانتى چاققان، ھەمىشە گۈزەل سۆزلەرنى تىزىپ چىقالايدۇ.","uning talanti chaqqan, hemishe güzel sözlerni tizip chiqalaydu."]],"打趣":[["别打趣我的尴尬经历。","مېنىڭ ناھايىتى ئىسكىنەرتلىك باشتىن كەچۈرگەنلىرىم بىلەن چاقچاق قىلما.","méning nahayiti iskinertlik bashtin kechürgenlirim bilen chaqchaq qilma."]],"成功感":[["完成目标后，他充满了成功感。","نىشاننى تاماملىغاندىن كېيىن، ئۇ مۇۋەپپەقىيەت تۇيغۇسىغا تولدى.","nishanni tamamlighandin kéyin, u muweppeqiyet tuyghusigha toldi."]],"承让人":[["承让人需要办理相关手续。","ۋارىس ئالغۇچى مۇناسىۋەتلىك رەسمىيەتلەرنى بېجىرىشى كېرەك.","waris alghuchi munasiwetlik resmiyetlerni béjirishi kérek."]],"拈酸":[["她拈酸吃醋，情绪低落。","ئۇ ئاچچىقلىنىپ ھەسەت قىلىپ، كەيپىياتى چۈشتى.","u achchiqlinip heset qilip, keypiyati chüshti."]],"抗炎性":[["这种药物具有抗炎性作用。","بۇ خىل دورا ياللۇغقا قارشى تۇرۇش رولىغا ئىگە.","bu xil dora yallughqa qarshi turush roligha ige."]],"扎款":[["这款扎款设计独特又时尚。","بۇ خىل زاچە لايىھە ئۆزگىچە ۋە زامانىۋىي.","bu xil zache layihe özgiche we zamaniwiy."]],"拙涩":[["他的文笔略显拙涩。","ئۇنىڭ يېزىش ئۇسلۇبى سەل قوپال.","uning yézish uslubi sel qopal."]],"拼图玩具":[["这套拼图玩具深受孩子们的喜爱。","بۇ پازل ئويۇنچۇقى بالىلارنىڭ ئالاھىدە ياخشى كۆرۈشىگە ئېرىشكەن.","bu pazl oyunchuqi balilarning alahide yaxshi körüshige érishken."]],"拿手菜":[["红烧肉是他的拿手菜。","قىزىل قورۇما ئۇنىڭ ماھارەتلىك تامىقى.","qizil qoruma uning maharetlik tamiqi."]],"捐血":[["他定期捐血救人。","ئۇ قەرەللىك قان ھەدىيە قىلىپ كىشىلەرنى قۇتقۇزىدۇ.","u qerellik qan hediye qilip kishilerni qutquzidu."]],"扫帚星":[["扫帚星带来厄运。","سۈپۈرگە يۇلتۇزى بەختسىزلىك ئېلىپ كېلىدۇ.","süpürge yultuzi bextsizlik élip kélidu."]],"掘墓工人":[["掘墓工人负责清理古墓中的杂物。","قەبرە قېزىغۇچى ئىشچىلار قەدىمكى قەبرىدىكى ئەخلەتلەرنى تازىلاشقا مەسئۇل.","qebre qézighuchi ishchilar qedimki qebridiki exletlerni tazilashqa mes'ul."]],"挽词":[["挽词表达了对逝者的深切怀念。","تەزىيە سۆزى مەرھۇمنى چوڭقۇر ئەسلەشنى ئىپادىلىدى.","teziye sözi merhumni chongqur esleshni ipadilidi."]],"提前投票":[["选民可以提前投票。","سايلامچىلار مۇددەتتىن بۇرۇن بېلەت تاشلىيالايدۇ.","saylamchilar muddettin burun bélet tashliyalaydu."]],"搜肠刮肚":[["他搜肠刮肚地想对策。","ئۇ چارە ئىزدەش ئۈچۈن مېڭىسىنى تىرىشىپ ئىشلەتتى.","u chare izdesh üchün méngisini tiriship ishletti."]],"扬菜":[["扬菜是一种需要翻锅技巧的烹饪方式。","ياڭسەي قازاننى ئاغدۇرۇش ماھارىتىنى تەلەپ قىلىدىغان بىر خىل تاماق ئېتىش ئۇسۇلىدۇر.","yangsey qazanni aghdurush maharitini telep qilidighan bir xil tamaq étish usulidur."]],"揣想":[["她揣想着未来的计划。","ئۇ كەلگۈسى پىلانىنى ئويلاپ چوڭقۇرلاشتى.","u kelgüsi pilanini oylap chongqurlashti."]],"揭载":[["报纸上揭载了这篇报道。","گېزىتتە بۇ خەۋەر ئېلان قىلىندى.","gézitte bu xewer élan qilindi."]],"摩根":[["摩根家族在金融界享有盛誉。","مورگان ئائىلىسى مالىيە ساھەسىدە يۇقىرى ئابرويغا ئىگە.","morgan ailisi maliye saheside yuqiri abroygha ige."]],"据实":[["他据实陈述，没有隐瞒。","ئۇ ھەقىقەتنى ئاساس قىلىپ بايان قىلدى، يوشۇرمىدى.","u heqiqetni asas qilip bayan qildi, yoshurmidi."]],"支使":[["他经常支使下属处理杂务。","ئۇ دائىم ئاستىدىكىلەرنى ئۇششاق ئىشلارنى بىر تەرەپ قىلىشقا بۇيرۇيدۇ.","u daim astidikilerni ushshaq ishlarni bir terep qilishqa buyruydu."]],"支承":[["这个结构需要良好的支承。","بۇ قۇرۇلما ياخشى تىرەككە ئېھتىياجلىق.","bu qurulma yaxshi tirekke éhtiyajliq."]],"支线":[["这条支线通往山区小镇。","بۇ تارماق يول تاغلىق رايوندىكى كىچىك بازىرىغا بارىدۇ.","bu tarmaq yol taghliq rayondiki kichik bazirigha baridu."]],"改选":[["公司即将举行改选。","شىركەت پات يېقىندا قايتا سايلام ئۆتكۈزىدۇ.","shirket pat yéqinda qayta saylam ötküzidu."]],"教练机":[["教练机用于飞行员的训练。","مەشىق ئايروپىلانى ئۇچقۇچىلارنىڭ مەشىقى ئۈچۈن ئىشلىتىلىدۇ.","meshiq ayropilani uchquchilarning meshiqi üchün ishlitilidu."]],"敬拜":[["信徒们敬拜神明。","مۆئمىنلەر خۇدالارغا چوقۇنىدۇ.","möminler xudalargha choqunidu."]],"拦河坝":[["拦河坝调节了水流。","دەريا بېغىنى تىزگىنلەپ ئېقىمنى تەڭشىدى.","derya béghini tizginlep éqimni tengshidi."]],"数珠":[["僧侣们使用数珠来辅助念佛。","روھانىيلار بۇددا ئوقۇشىغا ياردەم بېرىش ئۈچۈن تەسبىھ ئىشلىتىدۇ.","rohaniylar budda oqushigha yardem bérish üchün tesbih ishlitidu."]],"数量积":[["数量积在向量运算中很重要。","مىقدار كۆپەيتمىسى ۋېكتور ھېسابلاشىدا ئىنتايىن مۇھىمدۇر.","miqdar köpeytmisi wéktor hésablashida intayin muhimdur."]],"整除":[["这个数能被七整除。","بۇ ساننى يەتتىگە پۈتۈنلەي بۆلگىلى بولىدۇ.","bu sanni yettige pütünley bölgili bolidu."]],"文宗":[["这位文宗的书法作品闻名全国。","بۇ ۋېنزۇڭنىڭ خەتتاتلىق ئەسەرلىرى پۈتۈن مەملىكەتتە داڭلىق.","bu wénzungning xettatliq eserliri pütün memlikette dangliq."]],"文山区":[["文山区有许多历史古迹。","ۋېنشەن رايونىدا نۇرغۇن تارىخىي يادىكارلىقلار بار.","wénshen rayonida nurghun tarixiy yadikarliqlar bar."]],"斯捷潘":[["斯捷潘是俄罗斯作家。","ستېپان رۇسىيەلىك يازغۇچى.","stépan rusiyelik yazghuchi."]],"斗大":[["斗大是一所历史悠久的大学。","دودا چوڭ ئۇنىۋېرسىتېت ئۇزۇن تارىخقا ئىگە بىر ئۇنىۋېرسىتېتتۇر.","doda chong uniwérsitét uzun tarixqa ige bir uniwérsitéttur."]],"斯堪的纳维亚":[["斯堪的纳维亚半岛地形多样，风景优美。","سكاندىناۋىيە يېرىم ئارىلىنىڭ يەر شەكلى كۆپ خىل، مەنزىرىسى گۈزەل.","skandinawiye yérim arilining yer shekli köp xil, menzirisi güzel."]],"斯密约瑟":[["斯密约瑟是一位历史学家。","سمى يۈسۈپ بىر تارىخچى.","smi yüsüp bir tarixchi."]],"新沂市":[["新沂市以优质的农产品闻名。","شىنيى شەھىرى سۈپەتلىك يېزا ئىگىلىك مەھسۇلاتلىرى بىلەن تونۇلغان.","shinyi shehiri süpetlik yéza igilik mehsulatliri bilen tonulghan."]],"新潟县":[["新潟县以大米和温泉闻名。","نىئىگاتا ناھىيەسى گۈرۈچ ۋە ئىسسىق بۇلاق بىلەن داڭلىق.","niigata nahiyesi gürüch we issiq bulaq bilen dangliq."]],"新造":[["新造技术提升了效率。","يېڭى ئىجادىيەت تېخنىكىسى ئۈنۈمنى ئۆستۈردى.","yéngi ijadiyet téxnikisi ünümni östürdi."]],"新生儿":[["新生儿的健康状况良好。","يېڭى تۇغۇلغان بوۋاقلارنىڭ ساغلاملىق ئەھۋالى ياخشى.","yéngi tughulghan bowaqlarning saghlamliq ehwali yaxshi."]],"新宠":[["这只猫成了家里的新宠。","بۇ مۈشۈك ئائىلىنىڭ يېڭى ئەزىزىگە ئايلاندى.","bu müshük ailining yéngi ezizige aylandi."]],"新闻出版总署":[["新闻出版总署负责管理媒体事务。","خەۋەر نەشرىيات باش ئىدارىسى ئاخبارات ۋاسىتىلىرى ئىشلىرىنى باشقۇرىدۇ.","xewer neshriyat bash idarisi axbarat wasitiliri ishlirini bashquridu."]],"于都县":[["于都县历史悠久，文化丰富。","يۇدۇ ناھىيىسىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى مول.","yudu nahiyisining tarixi uzun, medeniyiti mol."]],"施密特":[["施密特教授发表了演讲。","پروفېسسور شمىدت نۇتۇق سۆزلىدى.","proféssor shmidt nutuq sözlidi."]],"施舍":[["他经常向乞丐施舍。","ئۇ كۆپىنچە تىلەمچىلەرگە سەدىقە بېرىدۇ.","u köpinche tilemchilerge sediqe béridu."]],"日俄战争":[["日俄战争是1904年至1905年间的冲突。","ياپونىيە-رۇسىيە ئۇرۇشى 1904-يىلدىن 1905-يىلغىچە بولغان توقۇنۇش ئىدى.","yaponiye-rusiye urushi 1904-yildin 1905-yilghiche bolghan toqunush idi."]],"日光浴":[["他喜欢在沙滩上享受日光浴。","ئۇ قۇملىقتا قۇياش نۇرىدىن ھۇزۇرلىنىشنى ياخشى كۆرىدۇ.","u qumliqta quyash nuridin huzurlinishni yaxshi köridu."]],"日较差":[["日较差影响作物生长。","كۈندۈزلۈك تېمپېراتۇرا پەرقى زىرائەتلەرنىڭ ئۆسۈشىگە تەسىر كۆرسىتىدۇ.","kündüzlük témpératura perqi ziraetlerning ösüshige tesir körsitidu."]],"日电":[["日电新闻及时更新。","كۈندىلىك ئېلېكترونلۇق خەۋەر ۋاقتىدا يېڭىلىنىپ تۇرىدۇ.","kündilik éléktronluq xewer waqtida yéngilinip turidu."]],"明矾":[["明矾常用于食品加工和净化水。","زەچ ياكى تۇتقۇن تاش ئوزۇقلۇق ئىشلەپچىقىرىش ۋە سۇنى تازىلاشتا كۆپ ئىشلىتىلىدۇ.","zech yaki tutqun tash ozuqluq ishlepchiqirish we suni tazilashta köp ishlitilidu."]],"明细表":[["财务报表中附有详细的明细表。","مالىيە دوكلاتىغا تەپسىلىي تەپسىلات جەدۋىلى قوشۇلغان.","maliye doklatigha tepsiliy tepsilat jedwili qoshulghan."]],"明虾":[["明虾是沿海地区常见的海鲜。","چوڭ راك دېڭىز بويى رايونلىرىدا كۆپ ئۇچرايدىغان دېڭىز مەھسۇلاتى.","chong rak déngiz boyi rayonlirida köp uchraydighan déngiz mehsulati."]],"明达":[["他为人明达，善于与人沟通。","ئۇ كىشى ئەقىللىق ۋە ئوچۇق كۆڭۈل، كىشىلەر بىلەن ئالاقە قىلىشقا ماھىر.","u kishi eqilliq we ochuq köngül, kishiler bilen alaqe qilishqa mahir."]],"易理解":[["这个概念很容易理解。","بۇ ئۇقۇم چۈشىنىشكە ئاسان.","bu uqum chüshinishke asan."]],"明珠暗投":[["明珠暗投，实在令人惋惜。","گۆھەرنى قاراڭغۇلۇققا تاشلىماق ھەقىقەتەن ئېسىنىشلىك.","göherni qarangghuluqqa tashlimaq heqiqeten ésinishlik."]],"易趣":[["易趣是一个购物平台。","ئىبەي بىر خىل سېتىۋېلىش سۇپىسى.","ibey bir xil sétiwélish supisi."]],"时间简史":[["《时间简史》是霍金的经典著作。","«ۋاقىتنىڭ قىسقىچە تارىخى» خوكىڭنىڭ كلاسسىك ئەسىرى.","«waqitning qisqiche tarixi» xokingning klassik esiri."]],"普天下":[["普天下皆大欢喜。","پۈتۈن دۇنيا خۇشال-خۇرام بولدى.","pütün dunya xushal-xuram boldi."]],"普通赤杨":[["普通赤杨是适应干旱环境的树木。","ئادەتتىكى قىزىل قېيىن قۇرغاقچىلىق مۇھىتىغا ماسلاشقان دەرەختۇر.","adettiki qizil qéyin qurghaqchiliq muhitigha maslashqan derextur."]],"普里切特":[["普里切特是一位著名作家。","پرىچېت ئاتاقلىق يازغۇچىدۇر.","prichét ataqliq yazghuchidur."]],"景县":[["景县位于河北省的东部。","جىڭ ناھىيىسى خېبېي ئۆلكىسىنىڭ شەرقىي قىسمىدا جايلاشقان.","jing nahiyisi xébéy ölkisining sherqiy qismida jaylashqan."]],"暴殄天物":[["他暴殄天物，把美食倒掉了。","ئۇ نېمەتلىك تائامنى تۆكۈۋېتىپ، نېمەتنى ئىسراپ قىلدى.","u németlik taamni töküwétip, németni israp qildi."]],"书名号":[["书名号用来标注书名。","كىتاب نامى بەلگىسى كىتاب نامىنى بەلگىلەش ئۈچۈن ئىشلىتىلىدۇ.","kitab nami belgisi kitab namini belgilesh üchün ishlitilidu."]],"书呆子":[["他是个十足的书呆子。","ئۇ پۈتۈنلەي كىتابخۇمار.","u pütünley kitabxumar."]],"有料":[["这篇文章内容很有料。","بۇ ماقالىنىڭ مەزمۇنى ئىنتايىن مول.","bu maqalining mezmuni intayin mol."]],"最新":[["最新的研究成果令人震惊。","ئەڭ يېڭى تەتقىقات نەتىجىلىرى ھەيران قالدۇرىدۇ.","eng yéngi tetqiqat netijiliri heyran qalduridu."]],"有丝分裂":[["细胞分裂过程中会发生有丝分裂。","ھۈجەيرە بۆلۈنۈش جەريانىدا مىتوز بولۇپ تۇرىدۇ.","hüjeyre bölünüsh jeryanida mitoz bolup turidu."]],"朝鲜半岛":[["朝鲜半岛历史上经历过多次战争。","چاۋشيەن يېرىم ئارىلى تارىختا كۆپ قېتىم ئۇرۇشنى باشتىن كەچۈرگەن.","chawshyen yérim arili tarixta köp qétim urushni bashtin kechürgen."]],"朗照":[["月光朗照大地。","ئاي نۇرى يەر يۈزىنى پارقىرىتىپ تۇرۇپتۇ.","ay nuri yer yüzini parqiritip turuptu."]],"未雨绸缪":[["要未雨绸缪。","ئالدىن تەييارلىق قىلىش كېرەك.","aldin teyyarliq qilish kérek."]],"末任":[["末任官员在任期间，努力整顿了秩序。","ئاخىرقى ۋەزىپىدار ئىش ئۈستىدە تەرتىپنى تۈزىتىشكە تىرىشتى.","axirqi wezipidar ish üstide tertipni tüzitishke tirishti."]],"东昌":[["东昌是山东省的一个历史名城。","دۇڭچاڭ شەندۇڭ ئۆلكىسىدىكى بىر تارىخىي شەھەر.","dungchang shendung ölkisidiki bir tarixiy sheher."]],"东缅高原":[["东缅高原地形复杂。","شەرقىي بىرما ئېگىزلىكىنىڭ يەر شەكلى مۇرەككەپ.","sherqiy birma égizlikining yer shekli murekkep."]],"东方黎族自治县":[["东方黎族自治县位于海南省。","شەرقىي لى مىللىتى ئاپتونوم ناھىيىسى خەينەن ئۆلكىسىدە جايلاشقان.","sherqiy li milliti aptonom nahiyisi xeynen ölkiside jaylashqan."]],"枸骨":[["枸骨叶片四季常绿。","گوگۇ يوپۇرمىقى تۆت پەسىلدە يېشىل تۇرىدۇ.","gogu yopurmiqi töt pesilde yéshil turidu."]],"柞栎":[["柞栎是一种生长缓慢的树木。","زوئۇلى بىر خىل ئاستا ئۆسىدىغان دەرەختۇر.","zouli bir xil asta ösidighan derextur."]],"柯西":[["柯西定理在数学中具有重要地位。","كوشى نەزەرىيىسى ماتېماتىكىدا مۇھىم ئورۇنغا ئىگە.","koshi nezeriyisi matématikida muhim orungha ige."]],"柱梁":[["柱梁结构是传统房屋的重要支撑。","تۈۋرۈك-تېرىك قۇرۇلمىسى ئەنئەنىۋى ئۆيلەرنىڭ مۇھىم تىرىكى.","tüwrük-térik qurulmisi en'eniwi öylerning muhim tiriki."]],"架空历史":[["这部小说属于架空历史题材。","بۇ رومان پەرەزىي تارىخ تېمىسىغا تەۋە.","bu roman pereziy tarix témisigha tewe."]],"校花":[["校花是学校里最美丽的女生。","مەكتەپ گۈلى مەكتەپتىكى ئەڭ گۈزەل قىز ئوقۇغۇچىدۇر.","mektep güli mekteptiki eng güzel qiz oqughuchidur."]],"格涅沙":[["格涅沙是当地的著名作家。","گېنېشا يەرلىك ئاتاقلىق يازغۇچى.","génésha yerlik ataqliq yazghuchi."]],"桑塔纳":[["桑塔纳以独特的建筑风格闻名。","سانتانا ئۆزىگە خاس بىناكارلىق ئۇسلۇبى بىلەن تونۇلغان.","santana özige xas binakarliq uslubi bilen tonulghan."]],"梵册贝叶":[["寺庙收藏梵册贝叶。","ئىبادەتخانا فەنزە بەتلىرىنى ساقلايدۇ.","ibadetxana fenze betlirini saqlaydu."]],"棉花拳击":[["这场棉花拳击比赛异常激烈。","بۇ پاختا بوكس مۇسابىقىسى ئىنتايىن كەسكىن بولدى.","bu paxta boks musabiqisi intayin keskin boldi."]],"梯板":[["梯板是楼梯的重要组成部分。","پەلەمپەي تاختىسى پەلەمپەينىڭ مۇھىم تەركىبىي قىسمىدۇر.","pelempey taxtisi pelempeyning muhim terkibiy qismidur."]],"棋赛":[["这场棋赛吸引了众多顶尖选手参与。","بۇ شاھمات مۇسابىقىسى نۇرغۇن يۇقىرى سەۋىيىلىك ماھىرلارنى جەلپ قىلدى.","bu shahmat musabiqisi nurghun yuqiri sewiyilik mahirlarni jelp qildi."]],"枣阳":[["枣阳是湖北省的一个城市。","زاۋياڭ خۇبېي ئۆلكىسىدىكى بىر شەھەر.","zawyang xubéy ölkisidiki bir sheher."]],"棚架格子":[["棚架格子设计得很巧妙。","كەپە رامكىنىڭ كاتەكچە لايىھىسى بەك ماھىرلىق بىلەن ئىشلەنگەن.","kepe ramkining katekche layihisi bek mahirliq bilen ishlengen."]],"极刑":[["极刑是一种极其严厉的惩罚方式。","ئەڭ ئېغىر جازا ئىنتايىن قاتتىق جازالاش ئۇسۇلىدۇر.","eng éghir jaza intayin qattiq jazalash usulidur."]],"极少":[["这种现象极少出现在日常生活中。","بۇ خىل ھادىسە كۈندىلىك تۇرمۇشتا ئىنتايىن ئاز كۆرۈلىدۇ.","bu xil hadise kündilik turmushta intayin az körülidu."]],"槽位":[["这个槽位正好适合安装设备。","بۇ ئوقۇر ئورنى ئۈسكۈنە قاچىلاشقا ماس كېلىدۇ.","bu oqur orni üsküne qachilashqa mas kélidu."]],"树袋熊":[["树袋熊喜欢吃桉树叶。","دەرەخ خالتىلىق ئېيىق ئېۋكالىپت يۇپۇرمىقىنى يېيىشنى ياخشى كۆرىدۇ.","derex xaltiliq éyiq éwkalipt yupurmiqini yéyishni yaxshi köridu."]],"桦甸市":[["桦甸市以林业闻名。","خۇاديەن شەھىرى ئورمانچىلىق بىلەن داڭلىق.","xuadyen shehiri ormanchiliq bilen dangliq."]],"樽罍":[["樽罍是古代的酒器。","زۇنلېي قەدىمكى شاراب ساۋىتى.","zunléy qedimki sharab sawiti."]],"桥段":[["桥段是故事的关键部分。","كۆۋرۈك بۆلىكى ھېكايىنىڭ مۇھىم قىسمى.","köwrük böliki hékayining muhim qismi."]],"机枪":[["士兵使用机枪压制敌人。","ئەسكەرلەر پۇشكىلىق مايىل قورال بىلەن دۈشمەننى بېسىقتۇردى.","eskerler pushkiliq mayil qoral bilen düshmenni bésiqturdi."]],"权当":[["权当是意外吧。","ۋاقىتلىق دەپ قاراڭ.","waqitliq dep qarang."]],"杠子":[["杠子是一种用于挑担的长杆。","گاڭزى يۈك كۆتۈرۈشكە ئىشلىتىلىدىغان ئۇزۇن تاياقتۇر.","gangzi yük kötürüshke ishlitilidighan uzun tayaqtur."]],"乐呵呵":[["他乐呵呵地笑着，心情格外好。","ئۇ خۇشال-خۇشال كۈلۈپ، كەيپىياتى ئالاھىدە ياخشى ئىدى.","u xushal-xushal külüp, keypiyati alahide yaxshi idi."]],"欲擒故纵":[["他欲擒故纵，故意放走猎物。","ئۇ قولغا چۈشۈرمەكچى بولۇپ قويۇۋەتتى، ئولجىنى قەستەن قويۇۋەتتى.","u qolgha chüshürmekchi bolup qoyuwetti, oljini qesten qoyuwetti."]],"欺人太甚":[["你欺人太甚，太过分了！","سەن بەك زىيانكەشلىك قىلدىڭ، بەك ئاشۇرۇۋەتتىڭ!","sen bek ziyankeshlik qilding, bek ashuruwetting!"]],"正儿八板":[["他正儿八板地完成了任务。","ئۇ ۋەزىپىنى جىددىي ئورۇندىدى.","u wezipini jiddiy orundidi."]],"正阳":[["正阳阳光强烈。","جېڭياڭنىڭ قۇياش نۇرى كۈچلۈك.","jéngyangning quyash nuri küchlük."]],"步韵":[["这首诗的步韵处理得非常巧妙。","بۇ شېئىرنىڭ قەدەم رىتىمى ئىنتايىن ماھىرلىق بىلەن بىر تەرەپ قىلىنغان.","bu shéirning qedem ritimi intayin mahirliq bilen bir terep qilinghan."]],"死棋":[["这步棋是死棋，无法挽回。","بۇ يۈرۈش ئۆلۈك يۈرۈش، قايتۇرۇۋالغىلى بولمايدۇ.","bu yürüsh ölük yürüsh, qayturuwalghili bolmaydu."]],"岁阑":[["岁阑时节，寒风中更显温暖。","يىل ئاخىرى پەسلىدە، سوغۇق شامالدا ئىللىقلىق تېخىمۇ بىلىنىدۇ.","yil axiri peslide, soghuq shamalda illiqliq téximu bilinidu."]],"历代志上":[["《历代志上》是圣经的重要典籍。","«تارىخنامە 1-كىتاب» ئىنجىلنىڭ مۇھىم كلاسسىك ئەسىرى.","«tarixname 1-kitab» injilning muhim klassik esiri."]],"毛虫":[["这只毛虫正在啃食树叶。","بۇ تۈكلۈك قۇرت دەرەخ يوپۇرمىقىنى كېمىرىۋاتىدۇ.","bu tüklük qurt derex yopurmiqini kémiriwatidu."]],"毒剂":[["毒剂是战争中使用的致命化学物质。","زەھەرلىك ماددا ئۇرۇشتا ئىشلىتىلىدىغان ئۆلۈمگە سەۋەب بولىدىغان خىمىيىلىك ماددىدۇر.","zeherlik madda urushta ishlitilidighan ölümge seweb bolidighan ximiyilik maddidur."]],"比附":[["不要随意比附他人。","باشقىلارغا قالايمىقان سېلىشتۇرماڭ.","bashqilargha qalaymiqan sélishturmang."]],"氢氧化镁":[["氢氧化镁可用于制作肥皂。","ھىدروگېن-ئوكسىدلانغان ماگنىي سوپۇن ياساشتا ئىشلىتىلىدۇ.","hidrogén-oksidlanghan magniy sopun yasashta ishlitilidu."]],"水落石出":[["真相终于水落石出。","ھەقىقەت ئاخىرى ئاشكارا بولدى.","heqiqet axiri ashkara boldi."]],"汗毛孔":[["汗毛孔能调节体温。","تەر تۆشۈكلىرى بەدەن تېمپېراتۇرىسىنى تەڭشەيدۇ.","ter töshükliri beden témpératurisini tengsheydu."]],"江湖一点诀":[["这本《江湖一点诀》很出名。","بۇ «جياڭخۇ بىر نۇقتا سىر» ئىنتايىن داڭلىق.","bu «jyangxu bir nuqta sir» intayin dangliq."]],"江湖骗子":[["那个江湖骗子骗走了很多钱。","ئۇ جياڭخۇ ئالدامچىسى نۇرغۇن پۇلنى ئالداپ كەتتى.","u jyangxu aldamchisi nurghun pulni aldap ketti."]],"江汉区":[["江汉区是武汉市的核心区域。","جياڭخەن رايونى ۋۇخەن شەھىرىنىڭ يادرو رايونى.","jyangxen rayoni wuxen shehirining yadro rayoni."]],"污辱":[["这种污辱让他感到屈辱。","بۇ خىل ھاقارەت ئۇنى خارلانغاندەك ھېس قىلدۇردى.","bu xil haqaret uni xarlanghandek hés qildurdi."]],"沁源县":[["沁源县以独特的自然风光吸引游客。","قىنيۈەن ناھىيىسى ئۆزگىچە تەبىئىي مەنزىرىسى بىلەن ساياھەتچىلەرنى جەلپ قىلىدۇ.","qinyüen nahiyisi özgiche tebiiy menzirisi bilen sayahetchilerni jelp qilidu."]],"沁阳市":[["沁阳市位于河南省的东南部。","قىنياڭ شەھىرى خېنەن ئۆلكىسىنىڭ شەرقىي جەنۇبىي قىسمىدا جايلاشقان.","qinyang shehiri xénen ölkisining sherqiy jenubiy qismida jaylashqan."]],"汽车站":[["汽车站位于城市的主要交通干道旁。","ئاپتوموبىل بېكىتى شەھەرنىڭ ئاساسلىق قاتناش تۇتاش يولىنىڭ بويىدا جايلاشقان.","aptomobil békiti sheherning asasliq qatnash tutash yolining boyida jaylashqan."]],"汽配":[["汽配市场汇集了各种汽车零件。","ئاپتوموبىل زاپچاسلىرى بازىرى ھەر خىل ئاپتوموبىل زاپچاسلىرىنى توپلىغان.","aptomobil zapchasliri baziri her xil aptomobil zapchaslirini toplighan."]],"没眼看":[["这场景真没眼看。","بۇ مەنزىرىنى ھەقىقەتەن كۆرگىلى بولمايدۇ.","bu menzirini heqiqeten körgili bolmaydu."]],"沙岩":[["沙岩是一种沉积岩。","شايەن بىر خىل چۆكۈندى تاغ جىنسى.","shayen bir xil chökündi tagh jinsi."]],"河心":[["河心有一座小岛。","دەريا مەركىزىدە بىر كىچىك ئارال بار.","derya merkizide bir kichik aral bar."]],"河津市":[["河津市是山西省运城市下辖的一个县级市。","خېجىن شەھىرى شەنشى ئۆلكىسى يۈنچېڭ شەھىرىگە قاراشلىق ناھىيە دەرىجىلىك شەھەردۇر.","xéjin shehiri shenshi ölkisi yünchéng shehirige qarashliq nahiye derijilik sheherdur."]],"沿滩区":[["沿滩区交通便捷。","يەنتەن رايونىنىڭ قاتناشى قولايلىق.","yenten rayonining qatnashi qolayliq."]],"油然而生":[["感动之情油然而生。","تەسىرلەنگەن ھېسسىيات مايدەك قايناپ چىقتى.","tesirlengen héssiyat maydek qaynap chiqti."]],"没影":[["他的承诺没影。","ئۇنىڭ ۋەدىسىنىڭ ئىزى يوق.","uning wedisining izi yoq."]],"法兰克":[["法兰克王国是中世纪的重要政权。","فاراڭك پادىشاھلىقى ئوتتۇرا ئەسىرنىڭ مۇھىم ھاكىمىيىتى.","farangk padishahliqi ottura esirning muhim hakimiyiti."]],"求亲":[["他向对方家庭求亲。","ئۇ قارشى تەرەپنىڭ ئائىلىسىدىن قىز سورىدى.","u qarshi terepning ailisidin qiz soridi."]],"汐止市":[["汐止市位于台湾西部。","شىجى شەھىرى تەيۋەننىڭ غەربىي قىسمىدا جايلاشقان.","shiji shehiri teywenning gherbiy qismida jaylashqan."]],"波塞冬":[["波塞冬是希腊神话中的海神。","پوسېيدون گرېتسىيە مىفولوگىيەسىدىكى دېڭىز ئىلاھىدۇر.","poséydon grétsiye mifologiyesidiki déngiz ilahidur."]],"泡影":[["他的梦想最终成了泡影。","ئۇنىڭ چۈشى ئاخىرىدا كۆپۈككە ئايلاندى.","uning chüshi axirida köpükke aylandi."]],"法定代表人":[["公司法定代表人签署了合同。","شىركەتنىڭ قانۇنىي ۋەكىلى توختامغا ئىمزا قويدى.","shirketning qanuniy wekili toxtamgha imza qoydi."]],"波丽士":[["波丽士是警察的别称。","پولىس پولىتسىيەنىڭ باشقا ئاتىلىشى.","polis politsiyening bashqa atilishi."]],"沼泽山雀":[["沼泽山雀喜欢在树上筑巢。","سازلىق چىۋىقى دەرەخلەرگە ئۇۋا ياساشنى ياخشى كۆرىدۇ.","sazliq chiwiqi derexlerge uwa yasashni yaxshi köridu."]],"洛克菲勒":[["洛克菲勒是石油巨头。","روكفېللېر نېفىت زومىگىرى.","rokféllér néfit zomigiri."]],"流网":[["流网用于捕捉海洋生物。","ئاقار تور دېڭىز جانلىقلىرىنى تۇتۇشقا ئىشلىتىلىدۇ.","aqar tor déngiz janliqlirini tutushqa ishlitilidu."]],"流刑":[["古代流刑通常将犯人发配边疆。","قەدىمكى زاماندا سۈرگۈن قىلىش ئادەتتە جازالانغۇچىنى چېگرا بويىغا ئەۋەتىش ئىدى.","qedimki zamanda sürgün qilish adette jazalanghuchini chégra boyigha ewetish idi."]],"浣女":[["浣女在溪边洗濯衣物。","قىز يۇيۇنچى ئېرىق بويىدا كىيىم يۇيىدۇ.","qiz yuyunchi ériq boyida kiyim yuyidu."]],"海底轮":[["在瑜伽中，海底轮是最基础的脉轮。","يۇگادا دېڭىز ئاستى چاقرىسى ئەڭ ئاساسىي چاقرا.","yugada déngiz asti chaqrisi eng asasiy chaqra."]],"海内存知己，天涯若比邻":[["海内存知己，天涯若比邻，情谊无远弗届。","دېڭىز ئىچىدە يېقىن دوست بولسا، دۇنيانىڭ ئۇ چېتىدىكىلەرمۇ قوشنا ئىكەندەك، دوستلۇق ھەر قانچە يىراق بولسىمۇ يېتىپ بارىدۇ.","déngiz ichide yéqin dost bolsa, dunyaning u chétidikilermu qoshna ikendek, dostluq her qanche yiraq bolsimu yétip baridu."]],"海蜇":[["海蜇的触手含有毒素，要小心触碰。","دېڭىز قىچىتىنىڭ پەللىرىدە زەھەر بار، ئۇنىڭغا ئېھتىيات بىلەن تەگكەن كېرەك.","déngiz qichitining pelliride zeher bar, uninggha éhtiyat bilen tegken kérek."]],"涵江区":[["涵江区位于福建省莆田市。","ھەنجياڭ رايونى فۇجيەن ئۆلكىسىنىڭ پۇتيەن شەھىرىدە جايلاشقان.","henjyang rayoni fujyen ölkisining putyen shehiride jaylashqan."]],"深不见底":[["这个洞深不见底。","بۇ تۆشۈكنىڭ تېگى يوق.","bu töshükning tégi yoq."]],"浮世绘":[["浮世绘展现了江户时代的风俗。","ئۇكىيوئې-رەسىم ئېدو دەۋرىنىڭ ئادەت-ئەنئەنىسىنى نامايان قىلىدۇ.","ukiyoé-resim édo dewrining adet-en'enisini namayan qilidu."]],"浩特":[["浩特是一个美丽的牧场。","خوت گۈزەل بىر يايلىق.","xot güzel bir yayliq."]],"准备金":[["公司预留了部分准备金。","شىركەت بىر قىسىم زاپاس مەبلەغ ئاجراتتى.","shirket bir qisim zapas meblegh ajratti."]],"减租":[["房东同意为租户减租。","ئۆي ئىگىسى ئىجارىدارغا ئىجارە ھەققىنى ئازايتىپ بېرىشكە قوشۇلدى.","öy igisi ijaridargha ijare heqqini azaytip bérishke qoshuldi."]],"游动":[["鱼在水里自由游动。","بېلىق سۇدا ئەركىن ئۈزىدۇ.","béliq suda erkin üzidu."]],"浉河区":[["浉河区位于河南省的西南部。","شىھې رايونى خېنەن ئۆلكىسىنىڭ جەنۇبىي غەربىي قىسمىدا جايلاشقان.","shihé rayoni xénen ölkisining jenubiy gherbiy qismida jaylashqan."]],"滑水道":[["滑水道是水上乐园的热门项目。","تېيىلىش ئۆستىڭى سۇ ئويۇن باغچىسىنىڭ قىزىق تۈرىدۇر.","téyilish östingi su oyun baghchisining qiziq türidur."]],"满腹牢骚":[["他总是满腹牢骚，对生活中的小事抱怨不停。","ئۇ ھەمىشە غۇدۇق-غۇدۇق ئاغرىنىپ، تۇرمۇشتىكى كىچىك ئىشلارغا توختىماي زارلىنىدۇ.","u hemishe ghuduq-ghuduq aghrinip, turmushtiki kichik ishlargha toxtimay zarlinidu."]],"汉末魏初":[["汉末魏初是中国历史上的动荡时期。","خەن سۇلالىسىنىڭ ئاخىرى ۋە ۋېي سۇلالىسىنىڭ باشلىنىشى جۇڭگو تارىخىدىكى تەۋرىنىشلىك دەۋردۇر.","xen sulalisining axiri we wéy sulalisining bashlinishi junggo tarixidiki tewrinishlik dewrdur."]],"渐稀":[["人群逐渐稀少，街道变得安静。","ئادەم توپى تەدرىجىي ئازىيىپ، كوچا جىمجىت بولۇپ قالدى.","adem topi tedrijiy aziyip, kocha jimjit bolup qaldi."]],"潮州":[["潮州以独特的潮州菜闻名。","چاۋجۇ ئۆزىگە خاس چاۋجۇ تائاملىرى بىلەن داڭلىق.","chawju özige xas chawju taamliri bilen dangliq."]],"潜行":[["特工在夜间潜行完成任务。","مەخسۇس ئەمەلدار كېچىدە يوشۇرۇن يۈرۈپ ۋەزىپىنى تاماملايدۇ.","mexsus emeldar kéchide yoshurun yürüp wezipini tamamlaydu."]],"潞城":[["潞城是历史悠久的古城。","لۇچېڭ ئۇزۇن تارىخقا ئىگە قەدىمىي شەھەر.","luchéng uzun tarixqa ige qedimiy sheher."]],"渑池县":[["渑池县以优质的农产品著称。","مېنچى ناھىيىسى سۈپەتلىك يېزا ئىگىلىك مەھسۇلاتلىرى بىلەن تونۇلغان.","ménchi nahiyisi süpetlik yéza igilik mehsulatliri bilen tonulghan."]],"湿透":[["暴雨中，他的衣服已经湿透了。","قويۇن يامغۇردا ئۇنىڭ كىيىمى پۈتۈنلەي نەم بولۇپ كەتتى.","qoyun yamghurda uning kiyimi pütünley nem bolup ketti."]],"湿黏":[["厨房的台面湿黏黏的，需要清理。","ئاشخانىنىڭ ئۈستىلى نەم يېپىشقاق بولۇپ، تازىلاش كېرەك.","ashxanining üstili nem yépishqaq bolup, tazilash kérek."]],"火麻":[["火麻是一种古老的植物。","قەنت كەندىرى قەدىمىي ئۆسۈملۈك تۈرى.","qent kendiri qedimiy ösümlük türi."]],"火箭筒":[["士兵用火箭筒发射火箭弹。","ئەسكەرلەر ئوت ئوقى تۇرۇبىسى بىلەن ئوت ئوقى ئاتتى.","eskerler ot oqi turubisi bilen ot oqi atti."]],"澳元":[["澳元是澳大利亚的官方货币。","ئاۋيۈەن ئاۋسترالىيەنىڭ رەسمىي پۇلى.","awyüen awstraliyening resmiy puli."]],"澳南沙锥":[["澳南沙锥是一种分布于澳大利亚的鸟类。","ئاۋنەن شاچۇي ئاۋسترالىيەدە تارقالغان بىر خىل قۇش.","awnen shachuy awstraliyede tarqalghan bir xil qush."]],"乌贼":[["乌贼是一种生活在海洋中的软体动物。","ئۇزەك دېڭىزدا ياشايدىغان يۇمشاق تەنلىك ھايۋاندۇر.","uzek déngizda yashaydighan yumshaq tenlik haywandur."]],"乌鱼":[["这道菜用的是新鲜乌鱼。","بۇ تائامدا يېڭى ئۇبەلاق بېلىقى ئىشلىتىلگەن.","bu taamda yéngi ubelaq béliqi ishlitilgen."]],"炸薯片":[["她喜欢吃炸薯片。","ئۇ پىشۇرۇلغان كارتوشكا قەلەمچىسى يېيىشنى ياخشى كۆرىدۇ.","u pishurulghan kartoshka qelemchisi yéyishni yaxshi köridu."]],"无以为报":[["受此恩惠，无以为报。","بۇ ياخشىلىققا رەھمەت قىلىشنىڭ ئامالى يوق.","bu yaxshiliqqa rehmet qilishning amali yoq."]],"无晶圆":[["无晶圆厂模式降低了生产成本。","فابرىكىسىز ئىشلەپچىقىرىش ئۇسۇلى ئىشلەپچىقىرىش چىقىمىنى تۆۋەنلەتتى.","fabrikisiz ishlepchiqirish usuli ishlepchiqirish chiqimini töwenletti."]],"无成":[["他因缺乏努力而一事无成。","ئۇ تىرىشچانلىقى يېتەرسىز بولغاچقا ھېچ ئىشقا ئېرىشەلمىدى.","u tirishchanliqi yétersiz bolghachqa héch ishqa érishelmidi."]],"无所不能":[["她无所不能，总能解决问题。","ئۇ ھەممە ئىشقا قادىر، ھەر دائىم مەسىلىنى ھەل قىلالايدۇ.","u hemme ishqa qadir, her daim mesilini hel qilalaydu."]],"无论何事":[["无论何事，都要冷静处理。","قانداق ئىش بولسىمۇ، سالقىن بىر تەرەپ قىلىش كېرەك.","qandaq ish bolsimu, salqin bir terep qilish kérek."]],"无路可走":[["被困在山上，他们无路可走。","تاغدا قاپسىلىپ قېلىپ، ئۇلارنىڭ ماڭىدىغان يولى يوق.","taghda qapsilip qélip, ularning mangidighan yoli yoq."]],"无量寿":[["佛经中提及无量寿佛。","بۇددا ئەسەرلىرىدە ئۆلچەمسىز ئۆمۈر بۇددىسى تىلغا ئېلىنغان.","budda eserliride ölchemsiz ömür buddisi tilgha élinghan."]],"熟路":[["这条街我熟路，闭眼都能走。","بۇ كوچىنى پىششىق بىلىمەن، كۆزۈمنى يۇمۇپمۇ ماڭالايمەن.","bu kochini pishshiq bilimen, közümni yumupmu mangalaymen."]],"营养学":[["营养学研究食物与健康的关系。","ئوزۇقلۇقشۇناسلىق يېمەكلىك بىلەن ساغلاملىق ئوتتۇرىسىدىكى مۇناسىۋەتنى تەتقىق قىلىدۇ.","ozuqluqshunasliq yémeklik bilen saghlamliq otturisidiki munasiwetni tetqiq qilidu."]],"烛火":[["烛火摇曳，映照出房间里的温馨氛围。","شام ئوتى لىپىلدەپ، ئۆيدىكى ئىللىق كەيپىياتنى ئەكس ئەتتۈرىدۇ.","sham oti lipildep, öydiki illiq keypiyatni eks ettüridu."]],"牙侩":[["牙侩从中赚取了丰厚的佣金。","تىش قاپىقى ئارىسىدا مول مۇكاپات ئالغان.","tish qapiqi arisida mol mukapat alghan."]],"牌楼":[["牌楼是古代的重要建筑。","تاق بىناسى قەدىمكى دەۋرنىڭ مۇھىم بىنالىرىدىن ئىدى.","taq binasi qedimki dewrning muhim binaliridin idi."]],"特等":[["他获得特等荣誉。","ئۇ ئالاھىدە دەرىجىلىك شەرەپكە ئېرىشتى.","u alahide derijilik sherepke érishti."]],"猜忌":[["两人因猜忌而产生了矛盾。","ئىككىيلەن گۇمان-پەرەز سەۋەبىدىن زىددىيەتكە چۈشۈپ قالدى.","ikkiylen guman-perez sewebidin ziddiyetke chüshüp qaldi."]],"王猛":[["王猛是著名的篮球运动员。","ۋاڭ مېڭ مەشھۇر باسكېتبول ماھىرى.","wang méng meshhur baskétbol mahiri."]],"玩忽职守":[["他因玩忽职守被严厉批评。","ئۇ بىپەرۋالىق بىلەن ۋەزىپىسىنى ئورۇندىمىغانلىقى ئۈچۈن قاتتىق تەنقىد قىلىندى.","u biperwaliq bilen wezipisini orundimighanliqi üchün qattiq tenqid qilindi."]],"珍宝":[["他收藏了许多珍贵的珍宝。","ئۇ نۇرغۇن قىممەتلىك خەزىنىلەرنى ساقلىدى.","u nurghun qimmetlik xezinilerni saqlidi."]],"田鼠":[["田鼠喜欢在田地里打洞。","دېڭىز چاشقىنى ئېتىزلىقتا ئۇۋا قېزىشنى ياخشى كۆرىدۇ.","déngiz chashqini étizliqta uwa qézishni yaxshi köridu."]],"申诉书":[["申诉书需要详细说明理由。","ئەرزنامە ئىلمە-تەپسىلاتلىق ھالدا سەۋەبىنى چۈشەندۈرۈشى كېرەك.","erzname ilme-tepsilatliq halda sewebini chüshendürüshi kérek."]],"甾酮":[["甾酮是一类重要的类固醇化合物。","ستېرون مۇھىم بىر تۈردىكى ستېروئىد بىرىكمىسىدۇر.","stéron muhim bir türdiki stéroid birikmisidur."]],"白额燕鸥":[["白额燕鸥在海岸边飞翔。","ئاق پېشانىلىك دېڭىز قارلىغىچى دېڭىز بويىدا ئۇچىدۇ.","aq péshanilik déngiz qarlighichi déngiz boyida uchidu."]],"白种":[["白种人通常居住在温带地区。","ئاق تەنلىكلەر ئادەتتە مۆتىدىل بەلباغ رايونلىرىدا ياشايدۇ.","aq tenlikler adette mötidil belbagh rayonlirida yashaydu."]],"百步穿杨":[["他的箭法百步穿杨。","ئۇنىڭ ئوق ئېتىش ماھارىتى يۈز ئادەمدىن بىرىنىڭ كۆزىنى تېشىپ چىقىدەك دەرىجىدە يۇقىرى.","uning oq étish mahariti yüz ademdin birining közini téship chiqidek derijide yuqiri."]],"矿藏":[["这里蕴藏着丰富的矿藏资源。","بۇ يەردە باي مەدەن بايلىقلىرى ساقلىنىپ ياتىدۇ.","bu yerde bay meden bayliqliri saqlinip yatidu."]],"磴口县":[["磴口县以独特的自然风光闻名。","دېڭكۇ ناھىيىسى ئۆزگىچە تەبىئىي مەنزىرىسى بىلەن داڭلىق.","déngku nahiyisi özgiche tebiiy menzirisi bilen dangliq."]],"穿透":[["光线能够穿透黑暗。","نۇر قاراڭغۇلۇقتىن سىڭىپ ئۆتەلەيدۇ.","nur qarangghuluqtin singip öteleydu."]]};
